def _pass():
    return {"farmer": ["PASS"], "hands": [], "market": []}


def _safe_get(d, key, default):
    if isinstance(d, dict):
        return d.get(key, default)
    return default


def _int(value, default=0):
    try:
        if value is None:
            return default
        return int(value)
    except Exception:
        return default


def _float(value, default=0.0):
    try:
        if value is None:
            return default
        return float(value)
    except Exception:
        return default


def _is_sequence(obj):
    return isinstance(obj, (list, tuple))


def _in_bounds(tiles, x, y):
    try:
        return 0 <= y < len(tiles) and 0 <= x < len(tiles[y])
    except Exception:
        return False


def _step_towards(fx, fy, tx, ty):
    if tx < fx:
        return ["WEST"]
    if tx > fx:
        return ["EAST"]
    if ty < fy:
        return ["NORTH"]
    if ty > fy:
        return ["SOUTH"]
    return ["PASS"]


def _manhattan(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])


def _fib_cost(n):
    a, b = 1, 1
    for _ in range(max(0, n)):
        a, b = b, a + b
    return a


def _quadrant(x, y, tiles):
    half = max(1, len(tiles) // 2)
    if x < half and y < half:
        return "NW"
    if x >= half and y < half:
        return "NE"
    if x < half and y >= half:
        return "SW"
    return "SE"


def _is_plant(tile):
    return isinstance(tile, dict) and _safe_get(tile, "kind", "") == "PLANT"


def _is_weed(tile):
    return isinstance(tile, dict) and _safe_get(tile, "kind", "") == "WEED"


def _plant_ready(tile, day):
    crop = _safe_get(tile, "crop", "WHEAT")
    yield_units = _int(_safe_get(tile, "yield_units", 0), 0)
    planted_day = _int(_safe_get(tile, "planted_day", 0), 0)
    age = max(0, day - planted_day)

    if crop in ONGOING_CROPS:
        return yield_units > 0

    max_day = CROP_MAX_DAY.get(crop, 4)
    max_yield = CROP_MAX_YIELD.get(crop, 4)

    if age >= max_day:
        return True
    if yield_units >= max_yield:
        return True

    return False


def _scan_active_crops(tiles):
    active = {}
    if not _is_sequence(tiles):
        return active

    for row in tiles:
        if not _is_sequence(row):
            continue
        for tile in row:
            if _is_plant(tile):
                crop = _safe_get(tile, "crop", "WHEAT")
                active[crop] = active.get(crop, 0) + 1

    return active


def _count_placed_animals(tiles):
    count = 0
    if not _is_sequence(tiles):
        return count

    for row in tiles:
        if not _is_sequence(row):
            continue
        for tile in row:
            if isinstance(tile, dict) and tile.get("kind") == "PASTURE":
                if tile.get("animal") is not None:
                    count += 1

    return count


def _count_empty_pastures(tiles):
    count = 0
    if not _is_sequence(tiles):
        return count

    for row in tiles:
        if not _is_sequence(row):
            continue
        for tile in row:
            if isinstance(tile, dict) and tile.get("kind") == "PASTURE":
                if tile.get("animal") is None:
                    count += 1

    return count


def _count_pastures(tiles):
    count = 0
    if not _is_sequence(tiles):
        return count

    for row in tiles:
        if not _is_sequence(row):
            continue
        for tile in row:
            if isinstance(tile, dict) and tile.get("kind") == "PASTURE":
                count += 1

    return count


def _desired_hands(day, money, active_crops, placed_animals):
    """Workload-based hiring target.

    Hands are paid in Fibonacci-scaled daily wages (they are re-hired from
    scratch every day), so we only pay for the work we actually have:
    watering/harvesting active crops, planting the current backlog, and
    feeding/caring for animals. The hire loop itself enforces affordability;
    here we return the workload target (never starve the crew just because
    money is low — more hands are what produce the money).
    """
    if day >= LIQUIDATION_DAY:
        return 2

    if not isinstance(active_crops, dict):
        active_crops = {}

    total_crops = sum(active_crops.values())

    # Strategy hiring curve:
    #  - Day 0: opening crew (5 hired at hour 0).
    #  - Day 1: keep the crew up to keep the melon/wheat wave watered.
    #  - Days 2-5: small crew waters/harvests the early wheat + melons.
    #  - Days 6-10: scale up for the strawberry transition.
    #  - Days 11+: near-max crew for the 3-quadrant operation.
    if day == 0:
        base = 5
    elif day <= 1:
        base = 5
    elif day <= 5:
        base = 3 + total_crops // 6 + placed_animals // 4
    elif day <= 10:
        base = 5 + total_crops // 5 + placed_animals // 3
    else:
        base = 7 + total_crops // 5 + placed_animals // 2

    floor = 3 if day <= 5 else 2
    return max(floor, min(HANDS_CAP, base))


def _sellable_inventory(item, shed, global_inventory, day, placed_animals):
    """
    v5.4: Strict shed-only selling.

    However, wheat and fertilizer reserves are calculated using global inventory
    so we do not accidentally sell feed wheat or fertilizer needed by workers.
    """
    shed_qty = _int(_safe_get(shed, item, 0), 0)
    if shed_qty <= 0:
        return 0

    if item == "WHEAT":
        global_qty = _int(global_inventory.get("WHEAT", 0), 0)

        if day >= 29:
            keep = 0
        elif day >= LIQUIDATION_DAY:
            keep = max(0, placed_animals * 2)
        else:
            keep = max(0, placed_animals * 2 + 3)

        excess = global_qty - keep
        if excess <= 0:
            return 0

        return min(shed_qty, excess)

    if item == "FERTILIZER":
        global_qty = _int(global_inventory.get("FERTILIZER", 0), 0)

        if day >= LIQUIDATION_DAY:
            keep = 0
        elif not ENABLE_FERTILIZER_CROP_USE:
            keep = 5
        elif day < 20:
            keep = 24
        else:
            keep = 8

        excess = global_qty - keep
        if excess <= 0:
            return 0

        return min(shed_qty, excess)

    return shed_qty


def _crop_cap(crop, planning_worker_count, unlocked_count):
    if crop == "MELON":
        return min(30, 8 + planning_worker_count * 2 + (unlocked_count - 1) * 5)

    if crop == "STRAWBERRY":
        return min(36, 8 + planning_worker_count * 2 + (unlocked_count - 1) * 6)

    if crop == "CARROT":
        return min(40, 6 + planning_worker_count + (unlocked_count - 1) * 8)

    if crop == "WHEAT":
        return min(40, 6 + planning_worker_count + (unlocked_count - 1) * 8)

    return 0


def _choose_target_crops(day, hour, money, seeds, active_crops, market_inventory,
                         planning_worker_count, unlocked_count):
    """Return an ordered list of crops we want to plant this turn.

    Phase-based priorities (top-player strategy):
      - Days 0-5:   melons (big Day-11 payday) with wheat for early cash.
      - Days 6-11:  strawberries take over; melons finish their second wave.
      - Days 12+:   strawberries are the endgame crop; carrots/wheat fill in.
    Only crops that still have seed stock and cap room are returned.
    """
    days_left = max(0, 30 - day)
    if days_left < 4:
        return []

    if day < 6:
        priority = ["MELON", "WHEAT", "CARROT"]
    elif day < 12:
        priority = ["STRAWBERRY", "MELON", "WHEAT"]
    else:
        # Wave-2 melons: buy on day ~11 and keep planting them for as long as
        # seeds remain and they can still mature before the end of the game.
        if (
            days_left >= MIN_PLANT_DAYS.get("MELON", 11)
            and _int(_safe_get(seeds, "MELON", 0), 0) > 0
        ):
            priority = ["MELON", "STRAWBERRY", "WHEAT"]
        else:
            priority = ["STRAWBERRY", "WHEAT"]

    result = []
    for crop in priority:
        if days_left < MIN_PLANT_DAYS.get(crop, 5):
            continue
        if _int(_safe_get(seeds, crop, 0), 0) > 0:
            active = active_crops.get(crop, 0)
            cap = _crop_cap(crop, planning_worker_count, unlocked_count)
            if active < cap:
                result.append(crop)

    return result


def _plant_budget(target_crops, seeds, active_crops, planning_worker_count, unlocked_count):
    """Per-crop planting slots: how many of each target crop to plant this turn."""
    budget = {}
    for crop in target_crops:
        have = _int(_safe_get(seeds, crop, 0), 0)
        active = active_crops.get(crop, 0)
        cap = _crop_cap(crop, planning_worker_count, unlocked_count)
        budget[crop] = max(0, min(have, cap - active))
    return budget


def _generate_tasks(tiles, day, target_crops, plant_budget, new_plant_limits,
                    shed, unit_inventories, unlocked_set, expected_workers):
    tasks = []
    planted_this_turn = {}

    if not _is_sequence(tiles):
        return tasks

    shed_cows = _int(_safe_get(shed, "COW", 0), 0)
    shed_sheep = _int(_safe_get(shed, "SHEEP", 0), 0)
    shed_wheat = _int(_safe_get(shed, "WHEAT", 0), 0)
    shed_fert = _int(_safe_get(shed, "FERTILIZER", 0), 0)

    carried_cows = 0
    carried_sheep = 0
    carried_wheat = 0
    carried_fert = 0

    for inv in unit_inventories:
        if isinstance(inv, dict):
            carried_cows += _int(inv.get("COW", 0), 0)
            carried_sheep += _int(inv.get("SHEEP", 0), 0)
            carried_wheat += _int(inv.get("WHEAT", 0), 0)
            carried_fert += _int(inv.get("FERTILIZER", 0), 0)

    total_cows_available = shed_cows + carried_cows
    total_sheep_available = shed_sheep + carried_sheep

    empty_pastures = _count_empty_pastures(tiles)
    total_pastures = _count_pastures(tiles)

    # Build pastures only when we own animals that need a home.
    total_animals_owned = total_cows_available + total_sheep_available
    total_animals_needed = min(MAX_ANIMALS, total_animals_owned)

    # Count unwatered plants.
    unwatered_plants = 0
    for row in tiles:
        if not _is_sequence(row):
            continue
        for tile in row:
            if _is_plant(tile) and not _safe_get(tile, "watered_today", False):
                unwatered_plants += 1

    # Loose planting cap to prevent tile utilization collapse.
    plant_capacity = max(8, expected_workers * 4)

    # Pasture positions follow the first unlocked quadrant.
    pasture_tiles = _pasture_tiles(unlocked_set)

    cows_to_place = total_cows_available
    sheep_to_place = total_sheep_available

    plantable_tiles = []

    for y, row in enumerate(tiles):
        if not _is_sequence(row):
            continue

        for x, tile in enumerate(row):
            if tile == "LOCKED":
                continue

            pos = (x, y)

            # Empty tile: build pasture or plant crop.
            if tile is None:
                if ENABLE_ANIMALS and pos in pasture_tiles:
                    if total_animals_owned > 0 and total_pastures < total_animals_needed:
                        quadrant = _quadrant(x, y, tiles)
                        if quadrant in unlocked_set:
                            tasks.append({
                                "pos": pos,
                                "type": "BUILD_PASTURE",
                                "priority": BUILD_PASTURE_PRIORITY,
                                "tokens": ["BUILD_PASTURE"],
                            })
                            continue

                if target_crops:
                    plantable_tiles.append(pos)

                continue

            # Weed.
            if _is_weed(tile):
                tasks.append({
                    "pos": pos,
                    "type": "DIG",
                    "priority": 20,
                    "tokens": ["DIG"],
                })
                continue

            # Pasture with animal.
            if isinstance(tile, dict) and tile.get("kind") == "PASTURE":
                animal = tile.get("animal")

                if animal is not None:
                    fed_today = bool(tile.get("fed_today", False))
                    consec_unfed = _int(tile.get("consecutive_unfed", 0), 0)
                    yield_units = _int(tile.get("yield_units", 0), 0)
                    cared_today = bool(tile.get("cared_today", False))
                    fertilizer_available = bool(tile.get("fertilizer_available", False))

                    # FEED. Normal feed (96) sits just above PLANT (95) so
                    # animal care is never starved by expansion planting, but
                    # below critical watering (98) and urgent feed (99).
                    if not fed_today:
                        feed_priority = 99 if consec_unfed >= 1 else 96
                        tasks.append({
                            "pos": pos,
                            "type": "FEED",
                            "priority": feed_priority,
                            "tokens": ["FEED"],
                            "req": "WHEAT",
                        })

                    # CARE
                    if not cared_today:
                        tasks.append({
                            "pos": pos,
                            "type": "CARE",
                            "priority": 94,
                            "tokens": ["CARE"],
                        })

                    # HARVEST animal product.
                    if yield_units > 0:
                        tasks.append({
                            "pos": pos,
                            "type": "HARVEST_ANIMAL",
                            "priority": 95,
                            "tokens": ["HARVEST"],
                        })

                    # COLLECT_FERTILIZER.
                    if fertilizer_available:
                        tasks.append({
                            "pos": pos,
                            "type": "COLLECT_FERTILIZER",
                            "priority": 82,
                            "tokens": ["COLLECT_FERTILIZER"],
                        })

                else:
                    # Empty pasture: place animal if available.
                    if cows_to_place > 0:
                        tasks.append({
                            "pos": pos,
                            "type": "PLACE",
                            "priority": ANIMAL_PICKUP_PRIORITY,
                            "tokens": ["PLACE", "COW"],
                            "req": "COW",
                        })
                        cows_to_place -= 1
                    elif sheep_to_place > 0:
                        tasks.append({
                            "pos": pos,
                            "type": "PLACE",
                            "priority": ANIMAL_PICKUP_PRIORITY,
                            "tokens": ["PLACE", "SHEEP"],
                            "req": "SHEEP",
                        })
                        sheep_to_place -= 1

                continue

            # Plant.
            if _is_plant(tile):
                if _plant_ready(tile, day):
                    tasks.append({
                        "pos": pos,
                        "type": "HARVEST",
                        "priority": 100,
                        "tokens": ["HARVEST"],
                    })
                else:
                    watered = bool(_safe_get(tile, "watered_today", False))
                    if not watered:
                        planted_day = _int(_safe_get(tile, "planted_day", 0), 0)
                        age = max(0, day - planted_day)
                        consec_unwatered = _int(_safe_get(tile, "consecutive_unwatered", 0), 0)

                        if consec_unwatered >= 1:
                            water_priority = 98
                        elif age == 0:
                            water_priority = 99
                        else:
                            water_priority = 93

                        tasks.append({
                            "pos": pos,
                            "type": "WATER",
                            "priority": water_priority,
                            "tokens": ["WATER"],
                        })

                    # Fertilizer crop usage temporarily disabled for stabilization.
                    if ENABLE_FERTILIZER_CROP_USE:
                        crop = _safe_get(tile, "crop", "WHEAT")
                        planted_day = _int(_safe_get(tile, "planted_day", 0), 0)
                        age = max(0, day - planted_day)

                        can_fertilize = False
                        if crop == "MELON" and 5 <= age <= 9:
                            can_fertilize = True
                        elif crop == "STRAWBERRY" and 8 <= age <= 15:
                            can_fertilize = True
                        elif crop == "WHEAT" and 2 <= age <= 3:
                            can_fertilize = True
                        elif crop == "CARROT" and age == 2:
                            can_fertilize = True

                        if can_fertilize and watered:
                            tasks.append({
                                "pos": pos,
                                "type": "FERTILIZE",
                                "priority": 76,
                                "tokens": ["FERTILIZE"],
                                "req": "FERTILIZER",
                            })

                continue

    # Plant crops nearest the shed first so crews work in a compact zone near
    # the shed (avoids planting the far corner and walking across the farm).
    if plantable_tiles and target_crops:
        plantable_tiles.sort(key=lambda p: _manhattan(p, SHED_POS))
        for pos in plantable_tiles:
            if unwatered_plants >= plant_capacity:
                break
            for crop in target_crops:
                if planted_this_turn.get(crop, 0) < plant_budget.get(crop, 0):
                    crop_limit = new_plant_limits.get(crop, 999)
                    if planted_this_turn.get(crop, 0) < crop_limit:
                        tasks.append({
                            "pos": pos,
                            "type": "PLANT",
                            "crop": crop,
                            "priority": PLANT_PRIORITY,
                            "tokens": ["PLANT", crop],
                        })
                        planted_this_turn[crop] = planted_this_turn.get(crop, 0) + 1
                        unwatered_plants += 1
                        break

    # Pickup animals from shed.
    if ENABLE_ANIMALS and empty_pastures > 0:
        pickup_slots = empty_pastures

        for _ in range(min(shed_cows, pickup_slots)):
            tasks.append({
                "pos": SHED_POS,
                "type": "PICKUP",
                "priority": ANIMAL_PICKUP_PRIORITY,
                "tokens": ["PICKUP", "COW", 1],
            })
            pickup_slots -= 1

        for _ in range(min(shed_sheep, pickup_slots)):
            tasks.append({
                "pos": SHED_POS,
                "type": "PICKUP",
                "priority": ANIMAL_PICKUP_PRIORITY,
                "tokens": ["PICKUP", "SHEEP", 1],
            })
            pickup_slots -= 1

    # Count animals needing feed.
    animals_need_feed = 0
    if _is_sequence(tiles):
        for row in tiles:
            if not _is_sequence(row):
                continue
            for tile in row:
                if isinstance(tile, dict) and tile.get("kind") == "PASTURE":
                    if tile.get("animal") is not None and not bool(tile.get("fed_today", False)):
                        animals_need_feed += 1

    # Pickup wheat if needed.
    if animals_need_feed > 0 and shed_wheat > 0 and carried_wheat < animals_need_feed:
        tasks.append({
            "pos": SHED_POS,
            "type": "PICKUP",
            "priority": 98,
            "tokens": ["PICKUP", "WHEAT", min(shed_wheat, animals_need_feed)],
        })

    # Pickup fertilizer only if fertilizer crop usage is enabled.
    if ENABLE_FERTILIZER_CROP_USE and shed_fert > 0 and carried_fert < 4:
        tasks.append({
            "pos": SHED_POS,
            "type": "PICKUP",
            "priority": 75,
            "tokens": ["PICKUP", "FERTILIZER", min(shed_fert, 4)],
        })

    return tasks


def _default_action(unit_pos, tiles):
    x, y = unit_pos
    if not _in_bounds(tiles, x, y):
        return ["PASS"]

    tile = tiles[y][x]
    if tile == "LOCKED":
        half = max(1, len(tiles) // 2)
        return _step_towards(x, y, half - 1, half - 1)

    return ["PASS"]


# Sticky task claims: each unit keeps the task it picked last turn until it
# completes it. This stops units from being yanked between tasks every turn
# (ping-pong), which was the main source of day-0 movement waste.
_TASK_CLAIMS = {"day": -1, "claims": {}}
CLAIM_BONUS = 3000          # keep-your-claimed-task edge (≈3 priority levels)
CLAIM_STEAL_PENALTY = 2000  # disincentive to grab another unit's task


def _task_key(task):
    pos = task.get("pos", None)
    if not _is_sequence(pos) or len(pos) < 2:
        return None
    return (int(pos[0]), int(pos[1]), task.get("type", ""), str(task.get("crop", "")))


def _assign_tasks_zoned(tasks, unit_positions, tiles, unlocked_set, plant_budget, unit_inventories, day=-1):
    active_quadrants = [q for q in ["NW", "NE", "SW", "SE"] if q in unlocked_set]
    if not active_quadrants:
        active_quadrants = ["NW"]

    # Prune claims: reset when the day changes (hands respawn), and drop claims
    # for tasks that no longer exist (completed, watered, or invalid).
    if _TASK_CLAIMS["day"] != day:
        _TASK_CLAIMS.update({"day": day, "claims": {}})
    claims = _TASK_CLAIMS["claims"]
    valid_keys = set()
    for task in tasks:
        k = _task_key(task)
        if k is not None:
            valid_keys.add(k)
    claims = {k: v for k, v in claims.items() if k in valid_keys}
    new_claims = {}

    # Unit-ordered assignment: each unit picks its own best (priority +
    # distance + zone affinity) task. This converges because the unit keeps
    # choosing the same task as it approaches it, instead of being yanked
    # around by a task-ordered loop. Tasks are pre-sorted by priority so a
    # critical task is preferred when scores tie at equal distances.
    tasks_sorted = sorted(tasks, key=lambda t: t.get("priority", 0), reverse=True)

    unit_actions = [None] * len(unit_positions)
    assigned_positions = set()
    assigned_plants = {}
    unit_count = max(1, len(unit_positions))

    unit_task_types = ["PASS"] * len(unit_positions)
    unit_task_priorities = [0] * len(unit_positions)

    for idx, unit_pos in enumerate(unit_positions):
        best_task = None
        best_score = -10**9

        for task in tasks_sorted:
            task_pos = task.get("pos", None)
            if not _is_sequence(task_pos) or len(task_pos) < 2:
                continue

            if task_pos in assigned_positions:
                continue

            task_type = task.get("type", "")

            if task_type == "PLANT":
                crop = task.get("crop", None)
                if assigned_plants.get(crop, 0) >= plant_budget.get(crop, 0):
                    continue

            task_req = task.get("req", None)
            if task_req is not None:
                inv = unit_inventories[idx] if idx < len(unit_inventories) else {}
                if _int(inv.get(task_req, 0), 0) <= 0:
                    continue

            distance = _manhattan(unit_pos, task_pos)
            task_quadrant = _quadrant(task_pos[0], task_pos[1], tiles)
            home_quadrant = active_quadrants[idx % len(active_quadrants)]
            second_quadrant = active_quadrants[(idx + 1) % len(active_quadrants)] if len(active_quadrants) > 1 else home_quadrant

            score = task.get("priority", 0) * 1000
            score -= distance * 50

            key = _task_key(task)
            if key is not None:
                claimer = claims.get(key)
                if claimer == idx:
                    score += CLAIM_BONUS
                elif claimer is not None:
                    score -= CLAIM_STEAL_PENALTY

            if task_quadrant == home_quadrant:
                score += 500
            elif task_quadrant == second_quadrant:
                score += 200
            elif task_quadrant in unlocked_set:
                score += 0
            else:
                score -= 10000

            if task_quadrant == home_quadrant:
                tile_owner = (task_pos[0] * 7 + task_pos[1] * 13) % unit_count
                if idx == tile_owner:
                    score += 300
                elif idx == (tile_owner + 1) % unit_count:
                    score += 100

            if score > best_score:
                best_score = score
                best_task = task

        if best_task is not None:
            task_pos = best_task["pos"]
            assigned_positions.add(task_pos)

            if best_task.get("type") == "PLANT":
                crop = best_task.get("crop", None)
                assigned_plants[crop] = assigned_plants.get(crop, 0) + 1

            k = _task_key(best_task)
            if k is not None:
                new_claims[k] = idx

            unit_task_types[idx] = best_task.get("type", "")
            unit_task_priorities[idx] = best_task.get("priority", 0)

            if unit_pos == task_pos:
                unit_actions[idx] = best_task.get("tokens", ["PASS"])
            else:
                unit_actions[idx] = _step_towards(
                    unit_pos[0],
                    unit_pos[1],
                    task_pos[0],
                    task_pos[1],
                )

    for idx in range(len(unit_positions)):
        if unit_actions[idx] is None:
            unit_actions[idx] = _default_action(unit_positions[idx], tiles)

    _TASK_CLAIMS["claims"] = new_claims

    return unit_actions, unit_task_types, unit_task_priorities


# -----------------------------
# Main agent
# -----------------------------

def agent(obs):
    try:
        if not isinstance(obs, dict):
            return _pass()

        player = _int(obs.get("player", 0), 0)
        day = _int(obs.get("day", 0), 0)
        hour = _int(obs.get("hour", 0), 0)

        farms = obs.get("farms", [])
        private = obs.get("private", {})

        if not isinstance(farms, list) or player >= len(farms):
            return _pass()

        me = farms[player]
        if not isinstance(me, dict):
            return _pass()

        money = _float(me.get("money", 0.0), 0.0)
        tiles = me.get("tiles", [])
        farmer = me.get("farmer", [0, 0])
        hands = me.get("hands", [])
        unlocked_quadrants = me.get("unlocked_quadrants", ["NW"])
        hires_today = _int(me.get("hires_today", 0), 0)

        unlocked_count = max(1, len(unlocked_quadrants))
        unlocked_set = set(unlocked_quadrants)

        if not _is_sequence(tiles) or len(farmer) < 2:
            return _pass()

        if not _is_sequence(hands):
            hands = []

        farmer_pos = (farmer[0], farmer[1])
        if not _in_bounds(tiles, farmer_pos[0], farmer_pos[1]):
            return _pass()

        unit_positions = [farmer_pos]
        for hand in hands:
            if _is_sequence(hand) and len(hand) >= 2:
                unit_positions.append((hand[0], hand[1]))
            else:
                unit_positions.append((0, 0))

        current_workers = len(unit_positions)

        shed = _safe_get(private, "shed", {})
        seeds = _safe_get(private, "seeds", {})
        inventories = _safe_get(private, "inventories", [])
        if not isinstance(inventories, list):
            inventories = []

        market_info = _safe_get(obs, "market", {})
        market_inventory = _safe_get(market_info, "inventory", {})

        # Global inventory is used only for reserves and buying decisions.
        global_inventory = {}

        if isinstance(shed, dict):
            for k, v in shed.items():
                global_inventory[k] = global_inventory.get(k, 0) + _int(v, 0)

        for inv in inventories:
            if isinstance(inv, dict):
                for k, v in inv.items():
                    global_inventory[k] = global_inventory.get(k, 0) + _int(v, 0)

        shed_total = sum(_int(v, 0) for v in (shed.values() if isinstance(shed, dict) else []))
        shed_pressure = shed_total / 100.0

        active_crops = _scan_active_crops(tiles)
        total_crop_count = sum(active_crops.values())
        days_left = max(0, 30 - day)

        placed_animals = _count_placed_animals(tiles)

        planning_workers = max(
            current_workers,
            _desired_hands(day, money, active_crops, placed_animals) + 1,
        )

        expected_workers = max(current_workers, _desired_hands(day, money, active_crops, placed_animals) + 1)

        target_crops = _choose_target_crops(
            day,
            hour,
            money,
            seeds,
            active_crops,
            market_inventory,
            planning_workers,
            unlocked_count,
        )

        plant_budget = _plant_budget(
            target_crops,
            seeds,
            active_crops,
            planning_workers,
            unlocked_count,
        )

        if hour >= 22:
            for crop in list(plant_budget.keys()):
                plant_budget[crop] = 0

        tasks = _generate_tasks(
            tiles,
            day,
            target_crops,
            plant_budget,
            MAX_NEW_PLANTS_PER_TURN,
            shed,
            inventories,
            unlocked_set,
            expected_workers,
        )

        unit_actions, unit_task_types, unit_task_priorities = _assign_tasks_zoned(
            tasks,
            unit_positions,
            tiles,
            unlocked_set,
            plant_budget,
            inventories,
            day,
        )

        # Priority-aware weed override.
        for i, unit_pos in enumerate(unit_positions):
            x, y = unit_pos
            if _in_bounds(tiles, x, y) and _is_weed(tiles[y][x]):
                if not PRIORITY_AWARE_WEED_OVERRIDE:
                    unit_actions[i] = ["DIG"]
                else:
                    if unit_task_priorities[i] < WEED_OVERRIDE_CRITICAL_THRESHOLD:
                        unit_actions[i] = ["DIG"]

        # -----------------------------
        # Market orders
        # -----------------------------

        buy_orders = []
        money_est = money

        # Day 0 opening: animal rush + fast crops + feed buffer (fits in 3000).
        if day == 0 and hour == 0:
            # HIRE 5 (cost 1+1+2+3+5 = 12).
            for i in range(OPENING_HIRE_COUNT):
                hire_cost = _fib_cost(i)
                if money_est >= hire_cost:
                    buy_orders.append(["HIRE"])
                    money_est -= hire_cost
                else:
                    break

            # 2 sheep + 2 cows: fertilizer + milk + wool engine for the season.
            if money_est >= 1000:
                buy_orders.append(["BUY_ANIMAL", "SHEEP", 2])
                money_est -= 1000

            if money_est >= 800:
                buy_orders.append(["BUY_ANIMAL", "COW", 2])
                money_est -= 800

            # 12 melon (Day-11 payday) + 7 wheat (early cash + future feed).
            if money_est >= 960:
                buy_orders.append(["BUY_SEED", "MELON", 12])
                money_est -= 960

            if money_est >= 70:
                buy_orders.append(["BUY_SEED", "WHEAT", 7])
                money_est -= 70

            # Feed buffer so the Day-0 animals never skip a meal on Day 1.
            if money_est >= 130:
                buy_orders.append(["BUY_PRODUCT", "WHEAT", 5])
                money_est -= 130

        else:
            # 1. Land expansion (strategy: NE day ~7, SW day ~11, no SE unless rich).
            if day < LIQUIDATION_DAY:
                if unlocked_count == 1 and day >= 6 and money_est >= 1050:
                    buy_orders.append(["BUY_LAND"])
                    money_est -= 1000

                elif unlocked_count == 2 and day >= 10 and money_est >= 2050:
                    buy_orders.append(["BUY_LAND"])
                    money_est -= 2000

                elif unlocked_count == 3 and day >= 14 and money_est >= 50100:
                    buy_orders.append(["BUY_LAND"])
                    money_est -= 4000

            # 2. Feed wheat reserve (2-day buffer; surplus feeds the market).
            if ENABLE_ANIMALS and day < 29 and placed_animals > 0:
                wheat_available = global_inventory.get("WHEAT", 0)
                wheat_target = placed_animals * 2 + 3

                if wheat_available < wheat_target:
                    deficit = min(10, wheat_target - wheat_available)
                    estimated_cost = deficit * 35

                    if money_est >= estimated_cost + 100:
                        buy_orders.append(["BUY_PRODUCT", "WHEAT", deficit])
                        money_est -= estimated_cost

            # 3. Hire workers (workload-based; leave 3 order slots for sells so
            # harvested produce does not pile up in the shed for a week).
            desired_hires = _desired_hands(day, money_est, active_crops, placed_animals)
            already_hired = hires_today

            hire_slot_cap = 7

            while len(buy_orders) < hire_slot_cap and already_hired < desired_hires:
                hire_cost = _fib_cost(already_hired)
                if day <= 3:
                    # Nearly broke on Day 1-3: spend everything on the crew.
                    if money_est < hire_cost:
                        break
                elif day <= 7:
                    # Days 4-7: keep the crew alive even when thin — the melon
                    # wave depends on daily watering; reserve stays tiny.
                    if money_est < hire_cost + 10:
                        break
                elif money_est < hire_cost + 50:
                    break

                buy_orders.append(["HIRE"])
                money_est -= hire_cost
                already_hired += 1

            # 4. Animals: day-0 pair is already in the shed; expand day 7+.
            owned_animals = (
                placed_animals
                + global_inventory.get("COW", 0)
                + global_inventory.get("SHEEP", 0)
            )

            if (
                ENABLE_ANIMALS
                and day >= 7
                and owned_animals < MAX_ANIMALS
                and len(buy_orders) < 7
            ):
                if money_est >= 800 + SAFE_MONEY_BUFFER and owned_animals + 2 <= MAX_ANIMALS:
                    buy_orders.append(["BUY_ANIMAL", "COW", 2])
                    money_est -= 800

                if (
                    money_est >= 1000 + SAFE_MONEY_BUFFER
                    and owned_animals + 4 <= MAX_ANIMALS
                    and len(buy_orders) < 7
                ):
                    buy_orders.append(["BUY_ANIMAL", "SHEEP", 2])
                    money_est -= 1000

            # 5. Phase-appropriate seed buying.
            buy_crops = _phase_buy_crops(day)

            for crop in buy_crops:
                if len(buy_orders) >= 7:
                    break

                active = active_crops.get(crop, 0)
                have = _int(_safe_get(seeds, crop, 0), 0)
                cap = _crop_cap(crop, planning_workers, unlocked_count)
                stock_target = SEED_TARGETS.get(crop, 12)

                if active + have >= min(cap, stock_target):
                    continue

                min_days = MIN_PLANT_DAYS.get(crop, 5)
                if days_left < min_days:
                    continue

                need = min(SEED_BATCHES.get(crop, 8), min(cap, stock_target) - (active + have))
                seed_cost = SEED_COST.get(crop, 10) * need

                if need > 0 and money_est >= seed_cost + SAFE_MONEY_BUFFER:
                    buy_orders.append(["BUY_SEED", crop, need])
                    money_est -= seed_cost

        # Endgame / shed pressure protection.
        if day >= LIQUIDATION_DAY:
            buy_orders = []
        elif shed_pressure >= SHED_PRESSURE_LIMIT:
            buy_orders = [
                order for order in buy_orders
                if order[0] == "BUY_LAND"
                or (order[0] == "BUY_PRODUCT" and len(order) > 1 and order[1] == "WHEAT")
            ]

        # Always reserve sell slots so harvested produce hits the market instead
        # of piling up in the shed; buys are capped to 7 orders above.
        sell_slots = max(0, 10 - len(buy_orders))
        endgame = day >= LIQUIDATION_DAY or shed_pressure >= SHED_PRESSURE_LIMIT

        daily_sold = _daily_sold(day)

        sell_candidates = []

        for item in SELLABLE_ITEMS:
            # Strict shed-only sell quantity.
            qty = _sellable_inventory(item, shed, global_inventory, day, placed_animals)
            if qty <= 0:
                continue

            item_inventory = _int(_safe_get(market_inventory, item, 10000), 10000)
            safe_inventory = SELL_SAFE_INVENTORY.get(item, 10100)

            sell_qty = 0

            if item in PREMIUM_DAILY_BUDGET:
                # Premium items are sold only below the safe market-inventory
                # threshold (rules constraint) and are paced by a daily budget
                # so we do not crash the market price with a single dump.
                if endgame:
                    sell_qty = qty
                else:
                    remaining = PREMIUM_DAILY_BUDGET[item] - daily_sold[item]
                    if remaining > 0 and item_inventory < safe_inventory:
                        sell_qty = min(qty, remaining)
                daily_sold[item] += sell_qty

            elif item == "FERTILIZER":
                if endgame:
                    sell_qty = qty
                elif item_inventory < safe_inventory:
                    sell_qty = min(3, qty)
                else:
                    sell_qty = 0

            elif item == "WHEAT":
                if endgame:
                    sell_qty = qty
                elif item_inventory < 10000:
                    sell_qty = min(6, qty)
                else:
                    sell_qty = 0

            elif endgame:
                sell_qty = qty

            else:
                if item_inventory < safe_inventory:
                    room = safe_inventory - item_inventory
                    max_tranche = 2 if item in PREMIUM_ITEMS else 6
                    sell_qty = min(qty, max(1, room), max_tranche)
                else:
                    if item in PREMIUM_ITEMS:
                        sell_qty = 0
                    else:
                        sell_qty = min(3, qty)

                if shed_pressure >= 0.85:
                    sell_qty = max(sell_qty, min(qty, 2))

            sell_qty = min(sell_qty, qty)

            if sell_qty > 0:
                estimated_value = BASE_PRICE.get(item, 1) * sell_qty
                sell_candidates.append((item, sell_qty, estimated_value))

        sell_candidates.sort(key=lambda entry: entry[2], reverse=True)

        sell_orders = []
        for item, qty, _ in sell_candidates[:sell_slots]:
            sell_orders.append(["SELL", item, qty])

        # Sells run first so the proceeds are available for the day's buys.
        market = sell_orders + buy_orders

        # Final safety filter for sell orders.
        final_market = []
        for order in market:
            if not _is_sequence(order) or len(order) == 0:
                continue

            if order[0] == "SELL" and len(order) >= 3:
                item = order[1]
                qty = _int(order[2], 0)
                available = _sellable_inventory(item, shed, global_inventory, day, placed_animals)

                if available >= qty:
                    final_market.append(order)
            else:
                final_market.append(order)

        market = final_market[:10]

        farmer_action = unit_actions[0] if unit_actions else ["PASS"]
        hand_actions = unit_actions[1:] if len(unit_actions) > 1 else []

        return {
            "farmer": farmer_action,
            "hands": hand_actions,
            "market": market,
        }

    except Exception:
        return _pass()

# qa_harness.py – Robust validation harness with crash-proof analysis
import json
import time
import statistics
from datetime import datetime, timezone
from collections import defaultdict

from kaggle_environments import make
from kaggriculture_rules import (
    # constants
    BOARD_SIZE, SHED_CAPACITY,
    # action strings
    PLANT, WATER, HARVEST, DIG, FEED, CARE, COLLECT_FERTILIZER, PLACE,
    BUILD_COOP, BUILD_PASTURE, PICKUP, DROP,
    SELL, BUY_SEED, BUY_ANIMAL, BUY_PRODUCT, HIRE, BUY_LAND,
    # validation helpers
    can_plant, can_water, can_harvest, can_feed, can_care, can_place, can_build,
    can_dig, can_pickup, can_drop, sell_legal, buy_legal,
    # utilities
    items_total,
)

DEFAULT_OPPONENTS = ["pass", "random", "starter"]
DEFAULT_SEEDS = [1, 2, 3]
DEFAULT_STEPS = 720


def to_number(value, default=None):
    try:
        return float(value) if value is not None else default
    except Exception:
        return default


def analyze_episode(steps, player=0):
    """
    Robust analysis that validates every action against kaggriculture_rules.
    Returns (metrics_dict, error_log_list).
    """
    metrics = {
        "final_money": 0,
        "unsold_items_endgame": 0,
        "estimated_overflow_discards": 0,
        "total_animal_days": 0,
        "cared_animal_days": 0,
        "escaped_animals": 0,
        "total_crop_days": 0,
        "watered_crop_days": 0,
        "died_crops": 0,
        "invalid_unit_actions": 0,
        "invalid_unit_action_details": defaultdict(int),
        "invalid_market_orders": 0,
        "invalid_market_order_details": defaultdict(int),
        "weeds_dug": 0,
        "max_tile_utilization": 0.0,
        "failed_market_orders": 0,
    }
    error_log = []

    if not steps:
        return metrics, error_log

    try:
        # ---------- Final state ----------
        try:
            final_obs = steps[-1][player]["observation"]
        except (IndexError, KeyError, TypeError):
            error_log.append("ERROR: Last step missing or malformed.")
            return metrics, error_log

        final_farm = final_obs["farms"][player]
        metrics["final_money"] = final_farm.get("money", 0)

        final_shed = final_obs["private"]["shed"]
        final_inventories = final_obs["private"].get("inventories", [])
        unsold = sum(v for v in final_shed.values() if isinstance(v, (int, float)))
        for inv in final_inventories:
            if isinstance(inv, dict):
                unsold += sum(v for v in inv.values() if isinstance(v, (int, float)))
        metrics["unsold_items_endgame"] = unsold

        # ---------- Per-step analysis ----------
        for i, step in enumerate(steps):
            if not step or len(step) <= player:
                continue
            agent_state = step[player]
            obs = agent_state.get("observation")
            if not obs:
                continue
            action = agent_state.get("action", {})
            day = obs.get("day", 0)
            hour = obs.get("hour", 0)
            farm = obs["farms"][player]
            tiles = farm["tiles"]
            unlocked = farm.get("unlocked_quadrants", ["NW"])
            private = obs.get("private", {})
            shed = private["shed"]
            seeds = private.get("seeds", {})
            inventories = private.get("inventories", [])

            # ---- Overflow (end of day) ----
            if hour == 23:
                total = items_total(obs)
                if total > SHED_CAPACITY:
                    overflow = total - SHED_CAPACITY
                    metrics["estimated_overflow_discards"] += overflow
                    error_log.append(
                        f"Day {day} Hour 23: Overflow risk – {total} items, {overflow} discarded."
                    )

            # ---- Tile utilisation ----
            unlocked_tiles = len(unlocked) * 25
            used = 0
            for row in tiles:
                if not isinstance(row, list):
                    continue
                for tile in row:
                    if isinstance(tile, dict) and tile.get("kind") in (
                        "PLANT", "PASTURE", "COOP"
                    ):
                        used += 1
            if unlocked_tiles > 0:
                metrics["max_tile_utilization"] = max(
                    metrics["max_tile_utilization"], used / unlocked_tiles
                )

            # ---- Crop & animal health (day end only) ----
            if hour == 23:
                for y, row in enumerate(tiles):
                    if not isinstance(row, list):
                        continue
                    for x, tile in enumerate(row):
                        if not isinstance(tile, dict):
                            continue
                        kind = tile.get("kind")
                        if kind == "PLANT":
                            metrics["total_crop_days"] += 1
                            if tile.get("watered_today"):
                                metrics["watered_crop_days"] += 1
                            unwatered = tile.get("consecutive_unwatered", 0)
                            if unwatered >= 2:
                                metrics["died_crops"] += 1
                                error_log.append(
                                    f"Day {day} Hour 23: Crop {tile.get('crop')} at ({x},{y}) died (unwatered {unwatered})."
                                )
                        elif kind in ("PASTURE", "COOP"):
                            animal = tile.get("animal")
                            if animal:
                                metrics["total_animal_days"] += 1
                                if tile.get("cared_today"):
                                    metrics["cared_animal_days"] += 1
                                unfed = tile.get("consecutive_unfed", 0)
                                if unfed >= 2:
                                    metrics["escaped_animals"] += 1
                                    error_log.append(
                                        f"Day {day} Hour 23: {animal} at ({x},{y}) escaped (unfed {unfed})."
                                    )

            # ---- Action validation ----
            if not action:
                continue

            farmer_action = action.get("farmer", [])
            hands_actions = action.get("hands", [])
            market_orders = action.get("market", [])

            # per-unit positions and inventories
            unit_positions = [tuple(farm["farmer"])]
            for hand in farm.get("hands", []):
                if hand and len(hand) >= 2:
                    unit_positions.append(tuple(hand))
                else:
                    unit_positions.append((0, 0))
            unit_inventories = []
            for idx in range(len(unit_positions)):
                if idx < len(inventories):
                    unit_inventories.append(inventories[idx])
                else:
                    unit_inventories.append({})

            all_unit_actions = [(farmer_action, unit_positions[0], 0)]
            for idx, h_act in enumerate(hands_actions):
                pos = unit_positions[idx + 1] if idx + 1 < len(unit_positions) else (0, 0)
                all_unit_actions.append((h_act, pos, idx + 1))

            for unit_act, pos, unit_idx in all_unit_actions:
                if not isinstance(unit_act, list) or len(unit_act) == 0:
                    continue
                cmd = unit_act[0]
                inv = unit_inventories[unit_idx]

                # ---- Validate each action type ----
                try:
                    if cmd == PLANT:
                        crop = unit_act[1] if len(unit_act) > 1 else None
                        legal, reason = can_plant(obs, pos, crop, inv)
                        if not legal:
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"][f"PLANT {crop} {reason}"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} PLANT {crop} at {pos} invalid: {reason}"
                            )
                    elif cmd == WATER:
                        if not can_water(obs, pos):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"]["WATER invalid target"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} WATER at {pos} invalid"
                            )
                    elif cmd == HARVEST:
                        if not can_harvest(obs, pos):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"]["HARVEST nothing to collect"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} HARVEST at {pos} invalid"
                            )
                    elif cmd == FEED:
                        if not can_feed(obs, pos, inv):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"]["FEED missing wheat/not needed"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} FEED at {pos} invalid"
                            )
                    elif cmd == CARE:
                        if not can_care(obs, pos, inv):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"]["CARE invalid"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} CARE at {pos} invalid"
                            )
                    elif cmd == COLLECT_FERTILIZER:
                        tx, ty = pos
                        tile = None
                        if 0 <= ty < len(tiles) and 0 <= tx < len(tiles[ty]):
                            tile = tiles[ty][tx]
                        if not (
                            isinstance(tile, dict)
                            and tile.get("kind") in ("PASTURE", "COOP")
                            and tile.get("animal")
                            and tile.get("fertilizer_available", False)
                        ):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"]["COLLECT_FERTILIZER none available"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} COLLECT_FERTILIZER at {pos} invalid"
                            )
                    elif cmd == PLACE:
                        animal = unit_act[1] if len(unit_act) > 1 else None
                        if not can_place(obs, pos, inv, animal):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"][f"PLACE {animal} invalid"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} PLACE {animal} at {pos} invalid"
                            )
                    elif cmd in (BUILD_COOP, BUILD_PASTURE):
                        structure = "COOP" if cmd == BUILD_COOP else "PASTURE"
                        if not can_build(obs, pos, structure):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"][f"{cmd} invalid target"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} {cmd} at {pos} invalid"
                            )
                    elif cmd == DIG:
                        tx, ty = pos
                        tile = None
                        if 0 <= ty < len(tiles) and 0 <= tx < len(tiles[ty]):
                            tile = tiles[ty][tx]
                        if isinstance(tile, dict) and tile.get("kind") == "WEED":
                            metrics["weeds_dug"] += 1
                        elif not can_dig(obs, pos):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"]["DIG nothing to clear"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} DIG at {pos} nothing to clear"
                            )
                    elif cmd == PICKUP:
                        item = unit_act[1] if len(unit_act) > 1 else None
                        qty = unit_act[2] if len(unit_act) > 2 else 1
                        if not can_pickup(obs, pos, inv, item, qty):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"][f"PICKUP {item} {qty} invalid"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} PICKUP {item} {qty} invalid"
                            )
                    elif cmd == DROP:
                        if not can_drop(obs, pos, inv):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"]["DROP invalid"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} DROP invalid"
                            )
                except Exception:
                    # don't let one action crash the whole analysis
                    metrics["invalid_unit_actions"] += 1
                    metrics["invalid_unit_action_details"]["exception during validation"] += 1

            # ---- Market orders ----
            simulated_money = farm["money"]
            simulated_hires = farm.get("hires_today", 0)
            for order in market_orders:
                if not isinstance(order, list) or len(order) < 2:
                    continue
                cmd = order[0]
                try:
                    if cmd == SELL:
                        if len(order) < 3:
                            continue
                        item, qty = order[1], order[2]
                        if not sell_legal(obs, item, qty):
                            metrics["failed_market_orders"] += 1
                            metrics["invalid_market_order_details"][
                                f"SELL {item} {qty} (shed had {shed.get(item, 0)})"
                            ] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: SELL {qty} {item} impossible – shed only has {shed.get(item, 0)}"
                            )
                    else:
                        item = order[1] if len(order) > 1 else None
                        qty = order[2] if len(order) > 2 else 1
                        valid, new_money, new_hires = buy_legal(
                            obs, cmd, item, qty, simulated_money, simulated_hires
                        )
                        if not valid:
                            metrics["invalid_market_orders"] += 1
                            metrics["invalid_market_order_details"][
                                f"{cmd} {item} {qty} unaffordable"
                            ] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: {cmd} {item} {qty} failed – not enough money"
                            )
                        else:
                            simulated_money = new_money
                            simulated_hires = new_hires
                except Exception:
                    # skip malformed order
                    continue
    except Exception as e:
        error_log.append(f"ERROR during analysis: {e}")

    # ---------- Rates ----------
    metrics["care_rate"] = (
        metrics["cared_animal_days"] / metrics["total_animal_days"]
        if metrics["total_animal_days"] > 0
        else 1.0
    )
    metrics["water_rate"] = (
        metrics["watered_crop_days"] / metrics["total_crop_days"]
        if metrics["total_crop_days"] > 0
        else 1.0
    )
    # Convert defaultdict to plain dict for JSON serialization
    metrics["invalid_unit_action_details"] = dict(metrics["invalid_unit_action_details"])
    metrics["invalid_market_order_details"] = dict(metrics["invalid_market_order_details"])

    return metrics, error_log


def run_one(agent="main.py", opponent="starter", steps=DEFAULT_STEPS, seed=None):
    config = {"episodeSteps": steps}
    if seed is not None:
        config["seed"] = seed

    started = time.time()
    try:
        env = make("kaggriculture", configuration=config, debug=False)
        env.run([agent, opponent])

        final_step = env.steps[-1]
        me = final_step[0]
        opp = final_step[1]

        deep_metrics, error_log = analyze_episode(env.steps, player=0)

        return {
            "agent": str(agent),
            "opponent": str(opponent),
            "seed": seed,
            "steps": len(env.steps),
            "status_me": str(me.status),
            "status_opponent": str(opp.status),
            "reward_me": to_number(me.reward),
            "reward_opponent": to_number(opp.reward),
            "runtime_seconds": round(time.time() - started, 2),
            "deep_metrics": deep_metrics,
            "error_log": error_log,
            "error": None,
        }
    except Exception as error:
        return {
            "agent": str(agent),
            "opponent": str(opponent),
            "seed": seed,
            "steps": None,
            "status_me": "ERROR",
            "status_opponent": "UNKNOWN",
            "reward_me": None,
            "reward_opponent": None,
            "runtime_seconds": round(time.time() - started, 2),
            "deep_metrics": {},
            "error_log": [],
            "error": repr(error),
        }


def is_win(result):
    return (result.get("reward_me") or 0) > (result.get("reward_opponent") or 0)


def evaluate_agent(
    agent="main.py",
    opponents=None,
    seeds=None,
    steps=DEFAULT_STEPS,
    save_results=True,
):
    if opponents is None:
        opponents = DEFAULT_OPPONENTS
    if seeds is None:
        seeds = DEFAULT_SEEDS

    results = []
    print("===== Kaggriculture QA Harness (Rules‑Based Validation) =====")
    print(f"Agent: {agent}")
    print(f"Opponents: {opponents}")
    print(f"Seeds: {seeds}")
    print(f"Steps per game: {steps}\n")

    for opponent in opponents:
        for seed in seeds:
            result = run_one(agent, opponent, steps, seed)
            results.append(result)

            status = result["status_me"]
            reward = result["reward_me"]
            opp_reward = result["reward_opponent"]
            err_log = result.get("error_log", [])

            print(
                f"opponent={result['opponent']} seed={result['seed']} "
                f"status={status} me={reward} opp={opp_reward} "
                f"time={result['runtime_seconds']}s"
            )
            if result["error"]:
                print(f"ERROR: {result['error']}")

            n_errors = len(err_log)
            if n_errors > 0:
                print(f"   Silent errors: {n_errors}")
                for msg in err_log[:3]:
                    print(f"     - {msg}")
                if n_errors > 3:
                    print(f"     ... and {n_errors - 3} more")

    valid = [r for r in results if r["status_me"] != "ERROR" and r["reward_me"] is not None]
    rewards = [r["reward_me"] for r in valid]

    summary = {
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "agent": str(agent),
        "total_games": len(results),
        "valid_games": len(valid),
        "error_games": len(results) - len(valid),
        "wins": sum(is_win(r) for r in valid),
        "win_rate": sum(is_win(r) for r in valid) / max(1, len(valid)),
        "average_reward": statistics.mean(rewards) if rewards else None,
        "median_reward": statistics.median(rewards) if rewards else None,
        "max_reward": max(rewards) if rewards else None,
    }

    print("\n===== SUMMARY =====")
    print(
        f"Total: {summary['total_games']} | Valid: {summary['valid_games']} | "
        f"Wins: {summary['wins']} ({summary['win_rate']:.2%})"
    )
    if rewards:
        print(
            f"Avg: {summary['average_reward']:.2f} | "
            f"Median: {summary['median_reward']:.2f} | Max: {summary['max_reward']:.2f}"
        )

    if valid:
        # ----- Aggregate reliability metrics -----
        all_care_rates = [r["deep_metrics"]["care_rate"] for r in valid]
        all_water_rates = [r["deep_metrics"]["water_rate"] for r in valid]
        total_escaped = sum(r["deep_metrics"]["escaped_animals"] for r in valid)
        total_died_crops = sum(r["deep_metrics"]["died_crops"] for r in valid)
        total_unsold = sum(r["deep_metrics"]["unsold_items_endgame"] for r in valid)
        total_overflow = sum(r["deep_metrics"]["estimated_overflow_discards"] for r in valid)
        total_invalid_unit = sum(r["deep_metrics"]["invalid_unit_actions"] for r in valid)
        total_invalid_market = sum(r["deep_metrics"]["invalid_market_orders"] for r in valid)
        total_failed_sells = sum(r["deep_metrics"]["failed_market_orders"] for r in valid)
        total_weeds = sum(r["deep_metrics"]["weeds_dug"] for r in valid)
        avg_util = statistics.mean([r["deep_metrics"]["max_tile_utilization"] for r in valid])

        merged_unit_details = defaultdict(int)
        merged_market_details = defaultdict(int)
        for r in valid:
            for k, v in r["deep_metrics"]["invalid_unit_action_details"].items():
                merged_unit_details[k] += v
            for k, v in r["deep_metrics"]["invalid_market_order_details"].items():
                merged_market_details[k] += v

        print("\n===== DEEP RELIABILITY METRICS =====")
        print(f"Avg Animal Care Rate:   {statistics.mean(all_care_rates):.2%}")
        print(f"Avg Crop Water Rate:    {statistics.mean(all_water_rates):.2%}")
        print(f"Total Escaped Animals:  {total_escaped}")
        print(f"Total Died Crops:       {total_died_crops}")
        print(f"Total Unsold End Items: {total_unsold}")
        print(f"Total Est. Overflow:    {total_overflow}")
        print(f"Total Failed Sells:     {total_failed_sells}")
        print(f"Total Invalid Unit Actions: {total_invalid_unit}")
        print(f"Total Invalid Market Orders: {total_invalid_market}")
        print(f"Total Weeds Dug:        {total_weeds}")
        print(f"Avg Max Tile Util:      {avg_util:.2%}")

        if merged_unit_details:
            print("\nMost Common Invalid Unit Actions:")
            for msg, count in sorted(merged_unit_details.items(), key=lambda x: x[1], reverse=True)[:5]:
                print(f"  - {msg}: {count}")
        if merged_market_details:
            print("\nMost Common Invalid Market Orders:")
            for msg, count in sorted(merged_market_details.items(), key=lambda x: x[1], reverse=True)[:5]:
                print(f"  - {msg}: {count}")

    if save_results:
        output = {"summary": summary, "results": results}
        with open("qa_results.json", "w") as f:
            json.dump(output, f, indent=2)
        print(f"\nSaved results to qa_results.json")

    return results


if __name__ == "__main__":
    evaluate_agent(
        agent="main.py",
        opponents=["pass", "random", "starter"],
        seeds=[1, 2, 3],
        steps=720,
    )

# qa_harness.py – Robust validation harness with crash-proof analysis
import json
import time
import statistics
from datetime import datetime, timezone
from collections import defaultdict

from kaggle_environments import make
from kaggriculture_rules import (
    # constants
    BOARD_SIZE, SHED_CAPACITY,
    # action strings
    PLANT, WATER, HARVEST, DIG, FEED, CARE, COLLECT_FERTILIZER, PLACE,
    BUILD_COOP, BUILD_PASTURE, PICKUP, DROP,
    SELL, BUY_SEED, BUY_ANIMAL, BUY_PRODUCT, HIRE, BUY_LAND,
    # validation helpers
    can_plant, can_water, can_harvest, can_feed, can_care, can_place, can_build,
    can_dig, can_pickup, can_drop, sell_legal, buy_legal,
    # utilities
    items_total,
)

DEFAULT_OPPONENTS = ["pass", "random", "starter"]
DEFAULT_SEEDS = [1, 2, 3]
DEFAULT_STEPS = 720


def to_number(value, default=None):
    try:
        return float(value) if value is not None else default
    except Exception:
        return default


def analyze_episode(steps, player=0):
    """
    Robust analysis that validates every action against kaggriculture_rules.
    Returns (metrics_dict, error_log_list).
    """
    metrics = {
        "final_money": 0,
        "unsold_items_endgame": 0,
        "estimated_overflow_discards": 0,
        "total_animal_days": 0,
        "cared_animal_days": 0,
        "escaped_animals": 0,
        "total_crop_days": 0,
        "watered_crop_days": 0,
        "died_crops": 0,
        "invalid_unit_actions": 0,
        "invalid_unit_action_details": defaultdict(int),
        "invalid_market_orders": 0,
        "invalid_market_order_details": defaultdict(int),
        "weeds_dug": 0,
        "max_tile_utilization": 0.0,
        "failed_market_orders": 0,
    }
    error_log = []

    if not steps:
        return metrics, error_log

    try:
        # ---------- Final state ----------
        try:
            final_obs = steps[-1][player]["observation"]
        except (IndexError, KeyError, TypeError):
            error_log.append("ERROR: Last step missing or malformed.")
            return metrics, error_log

        final_farm = final_obs["farms"][player]
        metrics["final_money"] = final_farm.get("money", 0)

        final_shed = final_obs["private"]["shed"]
        final_inventories = final_obs["private"].get("inventories", [])
        unsold = sum(v for v in final_shed.values() if isinstance(v, (int, float)))
        for inv in final_inventories:
            if isinstance(inv, dict):
                unsold += sum(v for v in inv.values() if isinstance(v, (int, float)))
        metrics["unsold_items_endgame"] = unsold

        # ---------- Per-step analysis ----------
        for i, step in enumerate(steps):
            if not step or len(step) <= player:
                continue
            agent_state = step[player]
            obs = agent_state.get("observation")
            if not obs:
                continue
            action = agent_state.get("action", {})
            day = obs.get("day", 0)
            hour = obs.get("hour", 0)
            farm = obs["farms"][player]
            tiles = farm["tiles"]
            unlocked = farm.get("unlocked_quadrants", ["NW"])
            private = obs.get("private", {})
            shed = private["shed"]
            seeds = private.get("seeds", {})
            inventories = private.get("inventories", [])

            # ---- Overflow (end of day) ----
            if hour == 23:
                total = items_total(obs)
                if total > SHED_CAPACITY:
                    overflow = total - SHED_CAPACITY
                    metrics["estimated_overflow_discards"] += overflow
                    error_log.append(
                        f"Day {day} Hour 23: Overflow risk – {total} items, {overflow} discarded."
                    )

            # ---- Tile utilisation ----
            unlocked_tiles = len(unlocked) * 25
            used = 0
            for row in tiles:
                if not isinstance(row, list):
                    continue
                for tile in row:
                    if isinstance(tile, dict) and tile.get("kind") in (
                        "PLANT", "PASTURE", "COOP"
                    ):
                        used += 1
            if unlocked_tiles > 0:
                metrics["max_tile_utilization"] = max(
                    metrics["max_tile_utilization"], used / unlocked_tiles
                )

            # ---- Crop & animal health (day end only) ----
            if hour == 23:
                for y, row in enumerate(tiles):
                    if not isinstance(row, list):
                        continue
                    for x, tile in enumerate(row):
                        if not isinstance(tile, dict):
                            continue
                        kind = tile.get("kind")
                        if kind == "PLANT":
                            metrics["total_crop_days"] += 1
                            if tile.get("watered_today"):
                                metrics["watered_crop_days"] += 1
                            unwatered = tile.get("consecutive_unwatered", 0)
                            if unwatered >= 2:
                                metrics["died_crops"] += 1
                                error_log.append(
                                    f"Day {day} Hour 23: Crop {tile.get('crop')} at ({x},{y}) died (unwatered {unwatered})."
                                )
                        elif kind in ("PASTURE", "COOP"):
                            animal = tile.get("animal")
                            if animal:
                                metrics["total_animal_days"] += 1
                                if tile.get("cared_today"):
                                    metrics["cared_animal_days"] += 1
                                unfed = tile.get("consecutive_unfed", 0)
                                if unfed >= 2:
                                    metrics["escaped_animals"] += 1
                                    error_log.append(
                                        f"Day {day} Hour 23: {animal} at ({x},{y}) escaped (unfed {unfed})."
                                    )

            # ---- Action validation ----
            if not action:
                continue

            farmer_action = action.get("farmer", [])
            hands_actions = action.get("hands", [])
            market_orders = action.get("market", [])

            # per-unit positions and inventories
            unit_positions = [tuple(farm["farmer"])]
            for hand in farm.get("hands", []):
                if hand and len(hand) >= 2:
                    unit_positions.append(tuple(hand))
                else:
                    unit_positions.append((0, 0))
            unit_inventories = []
            for idx in range(len(unit_positions)):
                if idx < len(inventories):
                    unit_inventories.append(inventories[idx])
                else:
                    unit_inventories.append({})

            all_unit_actions = [(farmer_action, unit_positions[0], 0)]
            for idx, h_act in enumerate(hands_actions):
                pos = unit_positions[idx + 1] if idx + 1 < len(unit_positions) else (0, 0)
                all_unit_actions.append((h_act, pos, idx + 1))

            for unit_act, pos, unit_idx in all_unit_actions:
                if not isinstance(unit_act, list) or len(unit_act) == 0:
                    continue
                cmd = unit_act[0]
                inv = unit_inventories[unit_idx]

                # ---- Validate each action type ----
                try:
                    if cmd == PLANT:
                        crop = unit_act[1] if len(unit_act) > 1 else None
                        legal, reason = can_plant(obs, pos, crop, inv)
                        if not legal:
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"][f"PLANT {crop} {reason}"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} PLANT {crop} at {pos} invalid: {reason}"
                            )
                    elif cmd == WATER:
                        if not can_water(obs, pos):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"]["WATER invalid target"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} WATER at {pos} invalid"
                            )
                    elif cmd == HARVEST:
                        if not can_harvest(obs, pos):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"]["HARVEST nothing to collect"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} HARVEST at {pos} invalid"
                            )
                    elif cmd == FEED:
                        if not can_feed(obs, pos, inv):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"]["FEED missing wheat/not needed"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} FEED at {pos} invalid"
                            )
                    elif cmd == CARE:
                        if not can_care(obs, pos, inv):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"]["CARE invalid"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} CARE at {pos} invalid"
                            )
                    elif cmd == COLLECT_FERTILIZER:
                        tx, ty = pos
                        tile = None
                        if 0 <= ty < len(tiles) and 0 <= tx < len(tiles[ty]):
                            tile = tiles[ty][tx]
                        if not (
                            isinstance(tile, dict)
                            and tile.get("kind") in ("PASTURE", "COOP")
                            and tile.get("animal")
                            and tile.get("fertilizer_available", False)
                        ):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"]["COLLECT_FERTILIZER none available"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} COLLECT_FERTILIZER at {pos} invalid"
                            )
                    elif cmd == PLACE:
                        animal = unit_act[1] if len(unit_act) > 1 else None
                        if not can_place(obs, pos, inv, animal):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"][f"PLACE {animal} invalid"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} PLACE {animal} at {pos} invalid"
                            )
                    elif cmd in (BUILD_COOP, BUILD_PASTURE):
                        structure = "COOP" if cmd == BUILD_COOP else "PASTURE"
                        if not can_build(obs, pos, structure):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"][f"{cmd} invalid target"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} {cmd} at {pos} invalid"
                            )
                    elif cmd == DIG:
                        tx, ty = pos
                        tile = None
                        if 0 <= ty < len(tiles) and 0 <= tx < len(tiles[ty]):
                            tile = tiles[ty][tx]
                        if isinstance(tile, dict) and tile.get("kind") == "WEED":
                            metrics["weeds_dug"] += 1
                        elif not can_dig(obs, pos):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"]["DIG nothing to clear"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} DIG at {pos} nothing to clear"
                            )
                    elif cmd == PICKUP:
                        item = unit_act[1] if len(unit_act) > 1 else None
                        qty = unit_act[2] if len(unit_act) > 2 else 1
                        if not can_pickup(obs, pos, inv, item, qty):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"][f"PICKUP {item} {qty} invalid"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} PICKUP {item} {qty} invalid"
                            )
                    elif cmd == DROP:
                        if not can_drop(obs, pos, inv):
                            metrics["invalid_unit_actions"] += 1
                            metrics["invalid_unit_action_details"]["DROP invalid"] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: Worker {unit_idx} DROP invalid"
                            )
                except Exception:
                    # don't let one action crash the whole analysis
                    metrics["invalid_unit_actions"] += 1
                    metrics["invalid_unit_action_details"]["exception during validation"] += 1

            # ---- Market orders ----
            simulated_money = farm["money"]
            simulated_hires = farm.get("hires_today", 0)
            for order in market_orders:
                if not isinstance(order, list) or len(order) < 2:
                    continue
                cmd = order[0]
                try:
                    if cmd == SELL:
                        if len(order) < 3:
                            continue
                        item, qty = order[1], order[2]
                        if not sell_legal(obs, item, qty):
                            metrics["failed_market_orders"] += 1
                            metrics["invalid_market_order_details"][
                                f"SELL {item} {qty} (shed had {shed.get(item, 0)})"
                            ] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: SELL {qty} {item} impossible – shed only has {shed.get(item, 0)}"
                            )
                    else:
                        item = order[1] if len(order) > 1 else None
                        qty = order[2] if len(order) > 2 else 1
                        valid, new_money, new_hires = buy_legal(
                            obs, cmd, item, qty, simulated_money, simulated_hires
                        )
                        if not valid:
                            metrics["invalid_market_orders"] += 1
                            metrics["invalid_market_order_details"][
                                f"{cmd} {item} {qty} unaffordable"
                            ] += 1
                            error_log.append(
                                f"Day {day} Hr {hour}: {cmd} {item} {qty} failed – not enough money"
                            )
                        else:
                            simulated_money = new_money
                            simulated_hires = new_hires
                except Exception:
                    # skip malformed order
                    continue
    except Exception as e:
        error_log.append(f"ERROR during analysis: {e}")

    # ---------- Rates ----------
    metrics["care_rate"] = (
        metrics["cared_animal_days"] / metrics["total_animal_days"]
        if metrics["total_animal_days"] > 0
        else 1.0
    )
    metrics["water_rate"] = (
        metrics["watered_crop_days"] / metrics["total_crop_days"]
        if metrics["total_crop_days"] > 0
        else 1.0
    )
    # Convert defaultdict to plain dict for JSON serialization
    metrics["invalid_unit_action_details"] = dict(metrics["invalid_unit_action_details"])
    metrics["invalid_market_order_details"] = dict(metrics["invalid_market_order_details"])

    return metrics, error_log


def run_one(agent="main.py", opponent="starter", steps=DEFAULT_STEPS, seed=None):
    config = {"episodeSteps": steps}
    if seed is not None:
        config["seed"] = seed

    started = time.time()
    try:
        env = make("kaggriculture", configuration=config, debug=False)
        env.run([agent, opponent])

        final_step = env.steps[-1]
        me = final_step[0]
        opp = final_step[1]

        deep_metrics, error_log = analyze_episode(env.steps, player=0)

        return {
            "agent": str(agent),
            "opponent": str(opponent),
            "seed": seed,
            "steps": len(env.steps),
            "status_me": str(me.status),
            "status_opponent": str(opp.status),
            "reward_me": to_number(me.reward),
            "reward_opponent": to_number(opp.reward),
            "runtime_seconds": round(time.time() - started, 2),
            "deep_metrics": deep_metrics,
            "error_log": error_log,
            "error": None,
        }
    except Exception as error:
        return {
            "agent": str(agent),
            "opponent": str(opponent),
            "seed": seed,
            "steps": None,
            "status_me": "ERROR",
            "status_opponent": "UNKNOWN",
            "reward_me": None,
            "reward_opponent": None,
            "runtime_seconds": round(time.time() - started, 2),
            "deep_metrics": {},
            "error_log": [],
            "error": repr(error),
        }


def is_win(result):
    return (result.get("reward_me") or 0) > (result.get("reward_opponent") or 0)


def evaluate_agent(
    agent="main.py",
    opponents=None,
    seeds=None,
    steps=DEFAULT_STEPS,
    save_results=True,
):
    if opponents is None:
        opponents = DEFAULT_OPPONENTS
    if seeds is None:
        seeds = DEFAULT_SEEDS

    results = []
    print("===== Kaggriculture QA Harness (Rules‑Based Validation) =====")
    print(f"Agent: {agent}")
    print(f"Opponents: {opponents}")
    print(f"Seeds: {seeds}")
    print(f"Steps per game: {steps}\n")

    for opponent in opponents:
        for seed in seeds:
            result = run_one(agent, opponent, steps, seed)
            results.append(result)

            status = result["status_me"]
            reward = result["reward_me"]
            opp_reward = result["reward_opponent"]
            err_log = result.get("error_log", [])

            print(
                f"opponent={result['opponent']} seed={result['seed']} "
                f"status={status} me={reward} opp={opp_reward} "
                f"time={result['runtime_seconds']}s"
            )
            if result["error"]:
                print(f"ERROR: {result['error']}")

            n_errors = len(err_log)
            if n_errors > 0:
                print(f"   Silent errors: {n_errors}")
                for msg in err_log[:3]:
                    print(f"     - {msg}")
                if n_errors > 3:
                    print(f"     ... and {n_errors - 3} more")

    valid = [r for r in results if r["status_me"] != "ERROR" and r["reward_me"] is not None]
    rewards = [r["reward_me"] for r in valid]

    summary = {
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "agent": str(agent),
        "total_games": len(results),
        "valid_games": len(valid),
        "error_games": len(results) - len(valid),
        "wins": sum(is_win(r) for r in valid),
        "win_rate": sum(is_win(r) for r in valid) / max(1, len(valid)),
        "average_reward": statistics.mean(rewards) if rewards else None,
        "median_reward": statistics.median(rewards) if rewards else None,
        "max_reward": max(rewards) if rewards else None,
    }

    print("\n===== SUMMARY =====")
    print(
        f"Total: {summary['total_games']} | Valid: {summary['valid_games']} | "
        f"Wins: {summary['wins']} ({summary['win_rate']:.2%})"
    )
    if rewards:
        print(
            f"Avg: {summary['average_reward']:.2f} | "
            f"Median: {summary['median_reward']:.2f} | Max: {summary['max_reward']:.2f}"
        )

    if valid:
        # ----- Aggregate reliability metrics -----
        all_care_rates = [r["deep_metrics"]["care_rate"] for r in valid]
        all_water_rates = [r["deep_metrics"]["water_rate"] for r in valid]
        total_escaped = sum(r["deep_metrics"]["escaped_animals"] for r in valid)
        total_died_crops = sum(r["deep_metrics"]["died_crops"] for r in valid)
        total_unsold = sum(r["deep_metrics"]["unsold_items_endgame"] for r in valid)
        total_overflow = sum(r["deep_metrics"]["estimated_overflow_discards"] for r in valid)
        total_invalid_unit = sum(r["deep_metrics"]["invalid_unit_actions"] for r in valid)
        total_invalid_market = sum(r["deep_metrics"]["invalid_market_orders"] for r in valid)
        total_failed_sells = sum(r["deep_metrics"]["failed_market_orders"] for r in valid)
        total_weeds = sum(r["deep_metrics"]["weeds_dug"] for r in valid)
        avg_util = statistics.mean([r["deep_metrics"]["max_tile_utilization"] for r in valid])

        merged_unit_details = defaultdict(int)
        merged_market_details = defaultdict(int)
        for r in valid:
            for k, v in r["deep_metrics"]["invalid_unit_action_details"].items():
                merged_unit_details[k] += v
            for k, v in r["deep_metrics"]["invalid_market_order_details"].items():
                merged_market_details[k] += v

        print("\n===== DEEP RELIABILITY METRICS =====")
        print(f"Avg Animal Care Rate:   {statistics.mean(all_care_rates):.2%}")
        print(f"Avg Crop Water Rate:    {statistics.mean(all_water_rates):.2%}")
        print(f"Total Escaped Animals:  {total_escaped}")
        print(f"Total Died Crops:       {total_died_crops}")
        print(f"Total Unsold End Items: {total_unsold}")
        print(f"Total Est. Overflow:    {total_overflow}")
        print(f"Total Failed Sells:     {total_failed_sells}")
        print(f"Total Invalid Unit Actions: {total_invalid_unit}")
        print(f"Total Invalid Market Orders: {total_invalid_market}")
        print(f"Total Weeds Dug:        {total_weeds}")
        print(f"Avg Max Tile Util:      {avg_util:.2%}")

        if merged_unit_details:
            print("\nMost Common Invalid Unit Actions:")
