def _default_action(unit_pos, tiles):
    x,y = unit_pos
    if not _in_bounds(tiles,x,y): return ["PASS"]
    tile = tiles[y][x]
    if tile == "LOCKED":
        half = max(1,len(tiles)//2)
        return _step_towards(x,y,half-1,half-1)
    return ["PASS"]

CLAIM_BONUS = 3000
CLAIM_STEAL_PENALTY = 2000

def _task_key(task):
    pos = task.get("pos")
    if not _is_sequence(pos) or len(pos)<2: return None
    return (int(pos[0]), int(pos[1]), task.get("type",""), str(task.get("crop","")))

def _assign_tasks_zoned(tasks, unit_positions, tiles, unlocked_set, plant_budget,
                        unit_inventories, target_crops, seeds, group_assignments, day=-1):
    global _TASK_CLAIMS
    active_quadrants = [q for q in ["NW","NE","SW","SE"] if q in unlocked_set]
    if not active_quadrants: active_quadrants = ["NW"]

    if _TASK_CLAIMS["day"] != day:
        _TASK_CLAIMS.update({"day": day, "claims": {}})
    claims = _TASK_CLAIMS["claims"]
    valid_keys = {_task_key(t) for t in tasks if _task_key(t) is not None}
    claims = {k:v for k,v in claims.items() if k in valid_keys}
    new_claims = {}

    ANIMAL_TASK_TYPES = {"BUILD_PASTURE", "FEED", "CARE", "PLACE",
                         "HARVEST_ANIMAL", "COLLECT_FERTILIZER", "PICKUP"}
    CROP_TASK_TYPES = {"PLANT", "WATER", "HARVEST", "FERTILIZE", "DIG"}
    FARMER_ANIMAL_BONUS = 8000
    FARMER_CROP_PENALTY = -2000

    tasks_sorted = sorted(tasks, key=lambda t: t.get("priority",0), reverse=True)

    worker_allowed_tasks = {}   
    worker_group_tiles = {}     
    for group_name, widx in group_assignments.items():
        if widx < len(unit_positions):
            group_tiles = set(CORNER_GROUPS.get(group_name, []))
            worker_group_tiles[widx] = group_tiles
            allowed = [t for t in tasks_sorted if tuple(t.get("pos", (-1,-1))) in group_tiles]
            worker_allowed_tasks[widx] = allowed

    tile_map = {}
    for t in tasks_sorted:
        p = t.get("pos")
        if p is not None: tile_map.setdefault(p,[]).append(t)

    unit_actions = [None]*len(unit_positions)
    assigned_pos = set()
    assigned_plants = {}
    unit_types = ["PASS"]*len(unit_positions)
    unit_prios = [0]*len(unit_positions)
    unit_cnt = max(1, len(unit_positions))

    for idx, upos in enumerate(unit_positions):
        if idx in worker_group_tiles:                
            group_tiles = worker_group_tiles[idx]
            if upos in tile_map:
                for task in tile_map[upos]:
                    if task["pos"] in assigned_pos: continue
                    if tuple(task["pos"]) not in group_tiles: continue
                    req = task.get("req")
                    if req is not None:
                        inv = unit_inventories[idx] if idx < len(unit_inventories) else {}
                        if _int(inv.get(req,0),0) <= 0: continue
                    unit_actions[idx] = task["tokens"]
                    assigned_pos.add(task["pos"])
                    if task.get("type") == "PLANT":
                        crop = task.get("crop")
                        assigned_plants[crop] = assigned_plants.get(crop,0) + 1
                    unit_types[idx] = task.get("type","")
                    unit_prios[idx] = task.get("priority",0)
                    break
            continue   

        if idx == 0:   
            if upos in tile_map:
                for task in tile_map[upos]:
                    if task["pos"] in assigned_pos: continue
                    req = task.get("req")
                    if req is not None:
                        inv = unit_inventories[idx] if idx < len(unit_inventories) else {}
                        if _int(inv.get(req,0),0) <= 0: continue
                    unit_actions[idx] = task["tokens"]
                    assigned_pos.add(task["pos"])
                    if task.get("type") == "PLANT":
                        crop = task.get("crop")
                        assigned_plants[crop] = assigned_plants.get(crop,0) + 1
                    unit_types[idx] = task.get("type","")
                    unit_prios[idx] = task.get("priority",0)
                    break
            continue

        if upos in tile_map:
            for task in tile_map[upos]:
                if tuple(task["pos"]) in _CORNER_TILE_SET: continue   
                if task["pos"] in assigned_pos: continue
                req = task.get("req")
                if req is not None:
                    inv = unit_inventories[idx] if idx < len(unit_inventories) else {}
                    if _int(inv.get(req,0),0) <= 0: continue
                unit_actions[idx] = task["tokens"]
                assigned_pos.add(task["pos"])
                if task.get("type") == "PLANT":
                    crop = task.get("crop")
                    assigned_plants[crop] = assigned_plants.get(crop,0) + 1
                unit_types[idx] = task.get("type","")
                unit_prios[idx] = task.get("priority",0)
                break

    for idx, upos in enumerate(unit_positions):
        if idx != 0: continue
        if unit_actions[idx] is not None: continue

        best, best_score = None, -10**9
        for task in tasks_sorted:
            tpos = task.get("pos")
            if not _is_sequence(tpos) or len(tpos)<2: continue
            if tuple(tpos) in _CORNER_TILE_SET: continue      
            if tpos in assigned_pos: continue
            if task.get("type")=="PLANT":
                crop = task.get("crop")
                if assigned_plants.get(crop,0) >= plant_budget.get(crop,0): continue
            req = task.get("req")
            if req is not None:
                inv = unit_inventories[idx] if idx < len(unit_inventories) else {}
                if _int(inv.get(req,0),0) <= 0: continue

            dist = _manhattan(upos, tpos)
            q = _quadrant(tpos[0], tpos[1], tiles)
            home = active_quadrants[idx % len(active_quadrants)]
            second = active_quadrants[(idx+1)%len(active_quadrants)] if len(active_quadrants)>1 else home

            score = task.get("priority",0)*1000 - dist*50

            ttype = task.get("type","")
            if ttype in ANIMAL_TASK_TYPES or (ttype == "PICKUP" and task.get("req") in ("COW","SHEEP","GOOSE")):
                score += FARMER_ANIMAL_BONUS
            elif ttype in CROP_TASK_TYPES:
                score += FARMER_CROP_PENALTY

            k = _task_key(task)
            if k is not None:
                claimer = claims.get(k)
                if claimer == idx: score += CLAIM_BONUS
                elif claimer is not None: score -= CLAIM_STEAL_PENALTY
            if q == home: score += 500
            elif q == second: score += 200
            elif q in unlocked_set: pass
            else: score -= 10000

            if score > best_score:
                best_score = score
                best = task

        if best is not None:
            assigned_pos.add(best["pos"])
            if best.get("type")=="PLANT":
                crop = best.get("crop")
                assigned_plants[crop] = assigned_plants.get(crop,0)+1
            k = _task_key(best)
            if k is not None: new_claims[k] = idx
            unit_types[idx] = best.get("type","")
            unit_prios[idx] = best.get("priority",0)
            if upos == best["pos"]:
                unit_actions[idx] = best["tokens"]
            else:
                unit_actions[idx] = _step_towards(upos[0],upos[1],best["pos"][0],best["pos"][1])

    for idx, upos in enumerate(unit_positions):
        if idx not in worker_allowed_tasks: continue
        if unit_actions[idx] is not None: continue

        allowed_tasks = worker_allowed_tasks[idx]
        best, best_score = None, -10**9

        for task in allowed_tasks:
            tpos = task.get("pos")
            if not _is_sequence(tpos) or len(tpos)<2: continue
            if tpos in assigned_pos: continue
            if task.get("type")=="PLANT":
                crop = task.get("crop")
                if assigned_plants.get(crop,0) >= plant_budget.get(crop,0): continue
            req = task.get("req")
            if req is not None:
                inv = unit_inventories[idx] if idx < len(unit_inventories) else {}
                if _int(inv.get(req,0),0) <= 0: continue

            dist = _manhattan(upos, tpos)
            score = task.get("priority",0)*1000 - dist*50

            if score > best_score:
                best_score = score
                best = task

        if best is not None:
            assigned_pos.add(best["pos"])
            if best.get("type")=="PLANT":
                crop = best.get("crop")
                assigned_plants[crop] = assigned_plants.get(crop,0)+1
            unit_types[idx] = best.get("type","")
            unit_prios[idx] = best.get("priority",0)
            if upos == best["pos"]:
                unit_actions[idx] = best["tokens"]
            else:
                unit_actions[idx] = _step_towards(upos[0],upos[1],best["pos"][0],best["pos"][1])
        else:
            unit_actions[idx] = ["PASS"]

    for idx, upos in enumerate(unit_positions):
        if idx == 0: continue                     
        if idx in worker_allowed_tasks: continue  
        if unit_actions[idx] is not None: continue

        best, best_score = None, -10**9
        for task in tasks_sorted:
            tpos = task.get("pos")
            if not _is_sequence(tpos) or len(tpos)<2: continue
            if tuple(tpos) in _CORNER_TILE_SET: continue   
            if tpos in assigned_pos: continue
            if task.get("type")=="PLANT":
                crop = task.get("crop")
                if assigned_plants.get(crop,0) >= plant_budget.get(crop,0): continue
            req = task.get("req")
            if req is not None:
                inv = unit_inventories[idx] if idx < len(unit_inventories) else {}
                if _int(inv.get(req,0),0) <= 0: continue

            dist = _manhattan(upos, tpos)
            q = _quadrant(tpos[0], tpos[1], tiles)
            home = active_quadrants[idx % len(active_quadrants)]
            second = active_quadrants[(idx+1)%len(active_quadrants)] if len(active_quadrants)>1 else home

            score = task.get("priority",0)*1000 - dist*50

            if task.get("type") == "PLANT" and tpos in MAGNET_TILES and dist == 1:
                score += 50000

            k = _task_key(task)
            if k is not None:
                claimer = claims.get(k)
                if claimer == idx: score += CLAIM_BONUS
                elif claimer is not None: score -= CLAIM_STEAL_PENALTY
            if q == home: score += 500
            elif q == second: score += 200
            elif q in unlocked_set: pass
            else: score -= 10000
            if q == home:
                tile_owner = (tpos[0]*7 + tpos[1]*13) % unit_cnt
                if idx == tile_owner: score += 300
                elif idx == (tile_owner+1)%unit_cnt: score += 100

            if score > best_score:
                best_score = score
                best = task

        if best is not None:
            assigned_pos.add(best["pos"])
            if best.get("type")=="PLANT":
                crop = best.get("crop")
                assigned_plants[crop] = assigned_plants.get(crop,0)+1
            k = _task_key(best)
            if k is not None: new_claims[k] = idx
            unit_types[idx] = best.get("type","")
            unit_prios[idx] = best.get("priority",0)
            if upos == best["pos"]:
                unit_actions[idx] = best["tokens"]
            else:
                unit_actions[idx] = _step_towards(upos[0],upos[1],best["pos"][0],best["pos"][1])

    for idx in range(len(unit_positions)):
        if unit_actions[idx] is not None: continue

        upos = unit_positions[idx]
        x, y = upos

        group_tiles = None
        for gname, widx in group_assignments.items():
            if widx == idx:
                group_tiles = set(CORNER_GROUPS.get(gname, []))
                break

        planted = False
        for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
            nx, ny = x+dx, y+dy
            if not _in_bounds(tiles, nx, ny): continue
            adj_pos = (nx, ny)

            if group_tiles is not None and adj_pos not in group_tiles:
                continue
            if group_tiles is None and adj_pos in _CORNER_TILE_SET:
                continue

            adj_tile = tiles[ny][nx]
            if adj_tile is None and adj_pos not in assigned_pos:
                for crop in target_crops:
                    if seeds.get(crop,0) > 0 and assigned_plants.get(crop,0) < plant_budget.get(crop,9999):
                        unit_actions[idx] = _step_towards(x, y, nx, ny)
                        assigned_pos.add(adj_pos)
                        assigned_plants[crop] = assigned_plants.get(crop,0) + 1
                        unit_types[idx] = "PLANT"
                        unit_prios[idx] = PRIORITY_PLANT
                        planted = True
                        break
            if planted:
                break

        if not planted:
            unit_actions[idx] = _default_action(unit_positions[idx], tiles)

    _TASK_CLAIMS["claims"] = new_claims
    return unit_actions, unit_types, unit_prios

