# ========== TEXT EXTRACTION ==========
def extract_text_from_pdf(pdf_bytes: bytes) -> str:
    """Extract text from digital PDF; fallback to OCR if no text."""
    text = ""
    try:
        with fitz.open(stream=pdf_bytes, filetype="pdf") as doc:
            for page in doc:
                text += page.get_text()
        if text.strip():
            return text
    except Exception as e:
        print(f"PDF text extraction failed: {e}")

    # OCR fallback
    print("No text layer, performing OCR on PDF...")
    try:
        with tempfile.NamedTemporaryFile(suffix=".pdf", delete=False) as tmp:
            tmp.write(pdf_bytes)
            tmp_path = tmp.name
        images = convert_from_path(tmp_path)
        os.unlink(tmp_path)
        ocr_text = ""
        for img in images:
            ocr_text += pytesseract.image_to_string(img) + "\n"
        return ocr_text
    except Exception as e:
        print(f"OCR failed: {e}")
        return ""


def extract_text_from_docx(docx_bytes: bytes) -> str:
    doc = Document(io.BytesIO(docx_bytes))
    text = "\n".join([para.text for para in doc.paragraphs])
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                text += "\n" + cell.text
    return text


def extract_text_from_image(image_bytes: bytes) -> str:
    img = Image.open(io.BytesIO(image_bytes))
    return pytesseract.image_to_string(img)


def extract_text(file_bytes: bytes, filename: str) -> str:
    ext = Path(filename).suffix.lower()
    if ext == ".pdf":
        return extract_text_from_pdf(file_bytes)
    elif ext == ".docx":
        return extract_text_from_docx(file_bytes)
    elif ext in [".png", ".jpg", ".jpeg", ".tiff", ".bmp"]:
        return extract_text_from_image(file_bytes)
    elif ext == ".txt":
        return file_bytes.decode("utf-8", errors="ignore")
    else:
        raise ValueError(f"Unsupported file type: {ext}")


# ========== LLM CALL ==========
def call_llm(text: str) -> Optional[Dict[str, Any]]:
    """Try to use local LLM. Return None if not connected or error."""
    if not LLM_URL:
        return None

    prompt = f"""
You are an expert CV parser. Extract the following information from the CV text below.
Return ONLY valid JSON (no additional commentary) with these exact keys:
{{
  "full_name": "",
  "email": "",
  "phone": "",
  "location": "",
  "linkedin": "",
  "website": "",
  "professional_summary": "",
  "work_experience": [
    {{
      "job_title": "",
      "company": "",
      "start_date": "",
      "end_date": "",
      "description": ""
    }}
  ],
  "education": [
    {{
      "degree": "",
      "institution": "",
      "start_date": "",
      "end_date": ""
    }}
  ],
  "skills": [],
  "certifications": [],
  "languages": []
}}

Rules:
- If a field is missing, leave it as empty string or empty list.
- Dates should be in "YYYY-MM-DD" format if possible, otherwise "YYYY-MM" or "YYYY".
- For work experience and education, include all entries, preserving chronological order.
- The "skills" array should contain individual skills, not categories.
- Do NOT invent information; only extract what is present.
- The output must be a single JSON object.

CV Text:
---
{text}
---
"""
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {LLM_API_KEY}"
    }
    payload = {
        "model": LLM_MODEL,
        "messages": [
            {"role": "system", "content": "You extract structured data from CVs. Respond only with JSON."},
            {"role": "user", "content": prompt}
        ],
        "temperature": 0.1,
        "max_tokens": 3000
    }

    try:
        response = requests.post(LLM_URL, headers=headers, json=payload, timeout=LLM_TIMEOUT)
        response.raise_for_status()
        content = response.json()["choices"][0]["message"]["content"]
        content = re.sub(r"^```json\s*|\s*```$", "", content.strip(), flags=re.MULTILINE)
        data = json.loads(content)
        return data
    except Exception as e:
        print(f"LLM call failed: {e}")
        return None


# ========== FALLBACK REGEX PARSER ==========
def fallback_extract(text: str) -> Dict[str, Any]:
    """Very simple regex/heuristic extraction for when LLM is unavailable."""
    data = {
        "full_name": "",
        "email": "",
        "phone": "",
        "location": "",
        "linkedin": "",
        "website": "",
        "professional_summary": "",
        "work_experience": [],
        "education": [],
        "skills": [],
        "certifications": [],
        "languages": []
    }

    # Email
    email_match = re.search(r'[\w\.-]+@[\w\.-]+\.\w+', text)
    if email_match:
        data["email"] = email_match.group(0)

    # Phone (basic)
    phone_match = re.search(r'(\+?\d{1,3}[\s-]?)?(\(?\d{2,4}\)?[\s-]?)?\d{3,4}[\s-]?\d{3,4}', text)
    if phone_match:
        data["phone"] = phone_match.group(0).strip()

    # LinkedIn
    linkedin_match = re.search(r'linkedin\.com/in/[A-Za-z0-9\-_]+', text, re.IGNORECASE)
    if linkedin_match:
        data["linkedin"] = linkedin_match.group(0)

    # Website (non-email)
    website_match = re.search(r'(https?://)?(www\.)?[a-zA-Z0-9\-]+\.[a-zA-Z]{2,}(/[^\s]*)?', text)
    if website_match and "linkedin" not in website_match.group(0).lower():
        data["website"] = website_match.group(0)

    # Name: assume first non-empty line, not containing contact keywords
    lines = [line.strip() for line in text.split('\n') if line.strip()]
    skip_words = ["email", "phone", "address", "linkedin", "www", "http", "@", "curriculum", "resume", "cv"]
    for line in lines[:10]:
        if not any(word in line.lower() for word in skip_words) and len(line.split()) <= 6:
            data["full_name"] = line.title()
            break

    # Location: look for common pattern "City, Country" or "City, ST"
    location_match = re.search(r'([A-Za-z]+(?:[ ,]+[A-Za-z]+){0,3}),\s*([A-Za-z]{2,})', text)
    if location_match:
        data["location"] = location_match.group(0)

    # Skills: extract lines under "Skills" heading
    skills_section = re.search(r'(?i)skills?\s*:?\s*(.*?)(?=\n\s*\n|\n[A-Z][a-z]+:)', text, re.DOTALL)
    if skills_section:
        skills_text = skills_section.group(1)
        skills = re.split(r'[,\n•|]', skills_text)
        data["skills"] = [s.strip() for s in skills if s.strip()][:30]

    # Experience: split by "Work Experience" heading if present
    exp_section = re.search(r'(?i)(work\s*experience|employment|professional\s*experience)\s*:?\s*(.*?)(?=\n\s*(?:education|skills|certifications|languages)\s*:?\s*|\Z)', text, re.DOTALL)
    if exp_section:
        exp_text = exp_section.group(2)
        # Split by common date patterns and job titles (very rough)
        entries = re.split(r'\n(?=[A-Z][a-z]+.*\b(19|20)\d{2}\b)', exp_text)
        for entry in entries:
            entry = entry.strip()
            if not entry:
                continue
            lines = entry.split('\n')
            # Assume first line contains job title and company
            title_company = lines[0] if lines else ""
            # Try to find dates
            dates = re.findall(r'((?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?\s+\d{4}|\d{4})', entry)
            start_date = dates[0] if dates else ""
            end_date = dates[1] if len(dates) > 1 else ""
            description = " ".join(lines[1:]) if len(lines) > 1 else ""
            data["work_experience"].append({
                "job_title": title_company,
                "company": "",
                "start_date": start_date,
                "end_date": end_date,
                "description": description
            })

    # Education: similar heuristic
    edu_section = re.search(r'(?i)education\s*:?\s*(.*?)(?=\n\s*(?:skills|work\s*experience|certifications|languages)\s*:?\s*|\Z)', text, re.DOTALL)
    if edu_section:
        edu_text = edu_section.group(1)
        entries = re.split(r'\n(?=[A-Z][a-z]+.*\b(19|20)\d{2}\b)', edu_text)
        for entry in entries:
            entry = entry.strip()
            if not entry:
                continue
            data["education"].append({
                "degree": entry.split('\n')[0] if entry else "",
                "institution": "",
                "start_date": "",
                "end_date": ""
            })

    # Certifications / Languages
    cert_match = re.search(r'(?i)certifications?\s*:?\s*(.*?)(?=\n\s*\n|\n[A-Z][a-z]+:)', text, re.DOTALL)
    if cert_match:
        data["certifications"] = [c.strip() for c in re.split(r'[,\n•|]', cert_match.group(1)) if c.strip()]

    lang_match = re.search(r'(?i)languages?\s*:?\s*(.*?)(?=\n\s*\n|\n[A-Z][a-z]+:)', text, re.DOTALL)
    if lang_match:
        data["languages"] = [l.strip() for l in re.split(r'[,\n•|]', lang_match.group(1)) if l.strip()]

    return data


# ========== VALIDATE STRUCTURE ==========
def validate_and_clean(data: Dict[str, Any]) -> Dict[str, Any]:
    required = {
        "full_name": str, "email": str, "phone": str, "location": str,
        "linkedin": str, "website": str, "professional_summary": str,
        "work_experience": list, "education": list,
        "skills": list, "certifications": list, "languages": list
    }
    cleaned = {}
    for key, typ in required.items():
        if key not in data or not isinstance(data[key], typ):
            cleaned[key] = [] if typ == list else ""
        else:
            cleaned[key] = data[key]

    # Clean work experience
    cleaned_we = []
    for exp in cleaned["work_experience"]:
        if isinstance(exp, dict):
            cleaned_we.append({
                "job_title": exp.get("job_title", ""),
                "company": exp.get("company", ""),
                "start_date": exp.get("start_date", ""),
                "end_date": exp.get("end_date", ""),
                "description": exp.get("description", "")
            })
    cleaned["work_experience"] = cleaned_we

    cleaned_edu = []
    for edu in cleaned["education"]:
        if isinstance(edu, dict):
            cleaned_edu.append({
                "degree": edu.get("degree", ""),
                "institution": edu.get("institution", ""),
                "start_date": edu.get("start_date", ""),
                "end_date": edu.get("end_date", "")
            })
    cleaned["education"] = cleaned_edu

    for key in ["skills", "certifications", "languages"]:
        cleaned[key] = [str(item) for item in cleaned[key] if item]

    return cleaned


# ========== DOCX GENERATION ==========
def generate_docx(data: Dict[str, Any]) -> bytes:
    """Return DOCX bytes from structured data."""
    doc = Document()
    doc.add_heading(data.get("full_name", ""), level=1)

    contact_parts = []
    if data.get("email"): contact_parts.append(f"Email: {data['email']}")
    if data.get("phone"): contact_parts.append(f"Phone: {data['phone']}")
    if data.get("location"): contact_parts.append(f"Location: {data['location']}")
    if data.get("linkedin"): contact_parts.append(f"LinkedIn: {data['linkedin']}")
    if data.get("website"): contact_parts.append(f"Website: {data['website']}")
    if contact_parts:
        doc.add_paragraph(" | ".join(contact_parts))

    if data.get("professional_summary"):
        doc.add_heading("Professional Summary", level=2)
        doc.add_paragraph(data["professional_summary"])

    if data.get("work_experience"):
        doc.add_heading("Work Experience", level=2)
        for exp in data["work_experience"]:
            title_company = exp.get("job_title", "")
            if exp.get("company"):
                title_company += f" at {exp['company']}"
            dates = ""
            if exp.get("start_date") or exp.get("end_date"):
                dates = f" ({exp.get('start_date', '')} - {exp.get('end_date', '')})"
            doc.add_heading(f"{title_company}{dates}", level=3)
            if exp.get("description"):
                doc.add_paragraph(exp["description"])

    if data.get("education"):
        doc.add_heading("Education", level=2)
        for edu in data["education"]:
            degree = edu.get("degree", "")
            institution = edu.get("institution", "")
            dates = ""
            if edu.get("start_date") or edu.get("end_date"):
                dates = f" ({edu.get('start_date', '')} - {edu.get('end_date', '')})"
            doc.add_paragraph(f"{degree} - {institution}{dates}")

    if data.get("skills"):
        doc.add_heading("Skills", level=2)
        doc.add_paragraph(", ".join(data["skills"]))

    if data.get("certifications"):
        doc.add_heading("Certifications", level=2)
        for cert in data["certifications"]:
            doc.add_paragraph(cert, style="List Bullet")

    if data.get("languages"):
        doc.add_heading("Languages", level=2)
        doc.add_paragraph(", ".join(data["languages"]))

    buffer = io.BytesIO()
    doc.save(buffer)
    buffer.seek(0)
    return buffer.getvalue()


