@app.get("/", response_class=HTMLResponse)
async def home():
    return FileResponse(STATIC_DIR / "index.html")


@app.post("/parse")
async def parse_cv(file: UploadFile = File(...)):
    # Read file bytes
    file_bytes = await file.read()
    filename = file.filename

    # Extract raw text
    try:
        raw_text = extract_text(file_bytes, filename)
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Text extraction failed: {e}")

    if not raw_text.strip():
        raise HTTPException(status_code=400, detail="Could not extract any text from the file.")

    # Try LLM first
    llm_data = call_llm(raw_text)
    llm_used = llm_data is not None
    warning = None

    if not llm_used:
        warning = "LLM not connected or failed. Using built-in extractor (lower accuracy)."
        data = fallback_extract(raw_text)
    else:
        data = llm_data

    # Validate and clean
    cleaned = validate_and_clean(data)

    # Add metadata
    result = {
        "llm_used": llm_used,
        "warning": warning,
        "data": cleaned,
        "raw_text": raw_text[:5000]  # send first 5000 chars for reference maybe
    }
    return JSONResponse(result)


class GenerateRequest(BaseModel):
    data: Dict[str, Any]


@app.post("/generate")
async def generate_cv(req: GenerateRequest):
    docx_bytes = generate_docx(req.data)
    return Response(
        content=docx_bytes,
        media_type="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        headers={"Content-Disposition": "attachment; filename=clean_cv.docx"}
    )


