// Toast Notification System

function showToast(message, type = 'info', duration = 5000) {
    // Create toast container if it doesn't exist
    let container = document.querySelector('.toast-container');
    if (!container) {
        container = document.createElement('div');
        container.className = 'toast-container';
        document.body.appendChild(container);
    }

    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;

    const icons = {
        success: '✅',
        error: '❌',
        info: 'ℹ️',
        warning: '⚠️'
    };

    toast.innerHTML = `
        <span class="toast-icon">${icons[type] || 'ℹ️'}</span>
        <div class="toast-content">${message}</div>
        <button class="toast-close" onclick="this.parentElement.remove()">&times;</button>
    `;

    container.appendChild(toast);

    // Auto-remove after duration
    if (duration > 0) {
        setTimeout(() => {
            if (toast.parentElement) {
                toast.style.opacity = '0';
                setTimeout(() => toast.remove(), 300);
            }
        }, duration);
    }
}

// Convenience functions
function showSuccess(message, duration = 5000) {
    showToast(message, 'success', duration);
}

function showError(message, duration = 7000) {
    showToast(message, 'error', duration);
}

function showInfo(message, duration = 5000) {
    showToast(message, 'info', duration);
}

function showWarning(message, duration = 7000) {
    showToast(message, 'warning', duration);
}

// Settings Management for LLM Configuration

class SettingsManager {
    constructor() {
        this.defaultSettings = {
            llmUrl: "http://localhost:8000/v1/chat/completions",
            llmModel: "local-model",
            apiKey: "not-needed",
            timeout: 30
        };

        this.settings = this.loadSettings();
        this.createSettingsButton();
        this.checkLLMConnectivity();
    }

    loadSettings() {
        const saved = localStorage.getItem('cvBuilderSettings');
        if (saved) {
            try {
                return { ...this.defaultSettings, ...JSON.parse(saved) };
            } catch (e) {
                console.warn('Failed to parse saved settings, using defaults');
                return { ...this.defaultSettings };
            }
        }
        return { ...this.defaultSettings };
    }

    saveSettings(settings = this.settings) {
        localStorage.setItem('cvBuilderSettings', JSON.stringify(settings));
    }

    createSettingsButton() {
        let btn = document.getElementById('settingsBtn');
        if (btn) return;

        btn = document.createElement('button');
        btn.id = 'settingsBtn';
        btn.className = 'settings-btn';
        btn.innerHTML = '⚙️ <span>Settings</span>';
        btn.onclick = () => this.showModal();
        document.body.appendChild(btn);

        // Position before theme toggle
        const themeToggle = document.getElementById('themeToggle');
        if (themeToggle && themeToggle.parentNode) {
            themeToggle.parentNode.insertBefore(btn, themeToggle);
        }
    }

    showModal() {
        // Create modal if it doesn't exist
        if (!document.getElementById('settingsModal')) {
            this.createSettingsModal();
        }

        const modal = document.getElementById('settingsModal');
        if (modal) {
            modal.style.display = 'block';
            // Populate fields with current settings
            document.getElementById('llmUrl').value = this.settings.llmUrl;
            document.getElementById('llmModel').value = this.settings.llmModel;
            document.getElementById('apiKey').value = this.settings.apiKey;
            document.getElementById('timeoutSlider').value = this.settings.timeout;
            document.getElementById('timeoutValue').textContent = this.settings.timeout + 's';
