        const textSpan = document.getElementById('testConnectionText');
        const statusSpan = document.getElementById('connectionStatus');

        btn.disabled = true;
        textSpan.innerHTML = '<span class="spinner"></span> Testing...';
        statusSpan.innerHTML = '';

        try {
            const response = await fetch('/test-llm', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    data: {
                        llm_url: this.settings.llmUrl,
                        llm_model: this.settings.llmModel,
                        api_key: this.settings.apiKey,
                        timeout: this.settings.timeout
                    }
                })
            });

            const result = await response.json();

            if (result.available) {
                statusSpan.innerHTML = '<span class="status-badge status-connected">✓ Connected</span>';
                showSuccess('LLM connection successful', 3000);
            } else {
                statusSpan.innerHTML = '<span class="status-badge status-disconnected">✗ Disconnected</span>';
                showError('Could not connect to LLM endpoint');
            }
        } catch (error) {
            statusSpan.innerHTML = '<span class="status-badge status-disconnected">✗ Error</span>';
            showError('Connection test failed: ' + error.message);
        } finally {
            btn.disabled = false;
            textSpan.textContent = 'Test Connection';
        }
    }

    async checkLLMConnectivity() {
        try {
            const response = await fetch('/health');
            if (response.ok) {
                const health = await response.json();
                this.updateLLMStatus(health.llm_available);
            }
        } catch (error) {
            console.warn('Health check failed:', error);
            this.updateLLMStatus(false);
        }
    }

    updateLLMStatus(available) {
        let statusEl = document.getElementById('llmStatus');
        if (!statusEl) {
            const header = document.querySelector('h1');
            if (header) {
                statusEl = document.createElement('div');
                statusEl.id = 'llmStatus';
                statusEl.style.marginTop = '0.5rem';
                header.parentNode.insertBefore(statusEl, header.nextSibling);
            }
        }

        if (statusEl) {
            statusEl.innerHTML = available 
                ? '<span class="status-badge status-connected">✓ LLM Connected - AI-Powered Parsing</span>'
                : '<span class="status-badge status-disconnected">⚠ LLM Disconnected - Using Fallback Parser</span>';
        }
    }
}

