// ===== Event Listeners =====
function initEventListeners() {
    // Theme toggle
    const themeToggle = $('themeToggle');
    if (themeToggle) themeToggle.addEventListener('click', toggleTheme);

    // Settings button
    const settingsBtn = $('settingsBtn');
    if (settingsBtn) settingsBtn.addEventListener('click', () => settingsManager.show());

    // Drag & drop
    const dropZone = $('dropZone');
    const fileInput = $('fileInput');
    const chooseBtn = $('chooseFileBtn');

    if (dropZone) {
        ['dragenter', 'dragover'].forEach(ev => {
            dropZone.addEventListener(ev, e => {
                e.preventDefault(); e.stopPropagation();
                dropZone.classList.add('dragover');
            });
        });
        ['dragleave', 'drop'].forEach(ev => {
            dropZone.addEventListener(ev, e => {
                e.preventDefault(); e.stopPropagation();
                dropZone.classList.remove('dragover');
            });
        });
        dropZone.addEventListener('drop', e => {
            e.preventDefault();
            dropZone.classList.remove('dragover');
            if (e.dataTransfer.files.length) handleFileSelect(e.dataTransfer.files[0]);
        });
        dropZone.addEventListener('keydown', e => {
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                fileInput?.click();
            }
        });
    }

    if (chooseBtn && fileInput) {
        chooseBtn.addEventListener('click', () => fileInput.click());
    }
    if (fileInput) {
        fileInput.addEventListener('change', e => {
            if (e.target.files.length) handleFileSelect(e.target.files[0]);
        });
    }

    // Preview tab switching
    document.querySelectorAll('.preview-tab').forEach(tab => {
        tab.addEventListener('click', () => {
            document.querySelectorAll('.preview-tab').forEach(t => t.classList.toggle('active', t === tab));
            // Both tabs show the same extracted text; OCR is handled during extraction
        });
    });

    // Remove file
    const removeBtn = $('removeFileBtn');
    if (removeBtn) removeBtn.addEventListener('click', removeFile);

    // Parse button
    const parseBtn = $('parseBtn');
    if (parseBtn) parseBtn.addEventListener('click', parseCV);

    // Generate button
    const generateBtn = $('generateBtn');
    if (generateBtn) generateBtn.addEventListener('click', generateDocx);

    // Add experience / education
    const addExp = $('addExperienceBtn');
    if (addExp) addExp.addEventListener('click', () => addExperienceItem({}));

    const addEdu = $('addEducationBtn');
    if (addEdu) addEdu.addEventListener('click', () => addEducationItem({}));

    // Keyboard shortcuts
    document.addEventListener('keydown', e => {
        if (e.ctrlKey && e.key === 'Enter' && !parseBtn?.disabled) {
            if (currentFile) parseCV();
        }
        if (e.ctrlKey && e.shiftKey && e.key === 'G') {
            if (!generateBtn?.disabled) generateDocx();
        }
        if (e.ctrlKey && e.key === ',') {
            e.preventDefault();
            settingsManager.show();
        }
    });
}

