// ===== File Handling =====
function removeFile() {
    currentFile = null; rawText = "";
    $('fileInput').value = '';
    $('filePreviewCard').style.display = 'none';
    $('progressCard').style.display = 'none';
    $('editCard').style.display = 'none';
    $('parseBtn').style.display = 'none';
    showToast('File removed', 'info', 2000);
}

async function handleFileSelect(file) {
    if (!file) return;

    // Validate extension
    const ext = '.' + (file.name.split('.').pop() || '').toLowerCase();
    const allowed = ['.pdf', '.docx', '.txt', '.png', '.jpg', '.jpeg', '.tiff', '.bmp'];
    if (!allowed.includes(ext)) {
        showToast(`Unsupported file type: ${ext}`, 'error');
        return;
    }

    // Validate size (50 MB)
    if (file.size > 50 * 1024 * 1024) {
        showToast('File too large. Maximum 50 MB.', 'error');
        return;
    }

    currentFile = file;
    $('previewFileName').textContent = file.name;
    $('previewFileSize').textContent = formatFileSize(file.size);
    $('filePreviewCard').style.display = 'block';
    $('editCard').style.display = 'none';
    $('parseBtn').style.display = 'inline-flex';
    $('parseBtn').disabled = false;
    $('parseBtn').innerHTML = '<i class="fas fa-cog"></i> Parse CV with AI';
    $('progressCard').style.display = 'none';

    // Reset preview text
    $('previewText').textContent = 'Extracting text…';
    $('previewMethod').textContent = 'Extracting';
    $('previewMethod').className = 'badge badge--info';

    // Extract text
    try {
        rawText = await extractTextFromFile(file);
        if (!rawText || !rawText.trim()) {
            $('previewText').textContent = 'No text could be extracted from this file.';
            $('previewMethod').textContent = 'Failed';
            $('previewMethod').className = 'badge badge--danger';
            $('parseBtn').disabled = true;
            showToast('No text extracted. Try a different file.', 'warning');
            return;
        }
        $('previewText').textContent = rawText.slice(0, 5000);
        const method = file.type.includes('pdf') ? 'Digital' : 'Text';
        $('previewMethod').textContent = method;
        $('previewMethod').className = 'badge badge--success';
        showToast(`Text extracted successfully (${formatFileSize(file.size)})`, 'success', 3000);
    } catch (err) {
        $('previewText').textContent = 'Error extracting text: ' + err.message;
        $('previewMethod').textContent = 'Error';
        $('previewMethod').className = 'badge badge--danger';
        $('parseBtn').disabled = true;
        showToast('Text extraction failed: ' + err.message, 'error');
    }
}

async function extractTextFromFile(file) {
    const ext = file.name.split('.').pop().toLowerCase();
    const arrayBuffer = await file.arrayBuffer();

    if (ext === 'pdf') return extractFromPDF(arrayBuffer);
    if (ext === 'docx') return extractFromDocx(arrayBuffer);
    if (ext === 'txt') return extractFromText(arrayBuffer);
    if (['png', 'jpg', 'jpeg', 'tiff', 'bmp'].includes(ext)) return extractFromImage(file);
    throw new Error('Unsupported file type');
}

// ── PDF ──────────────────────────────────────────────────────
async function extractFromPDF(arrayBuffer) {
    if (typeof pdfjsLib === 'undefined') throw new Error('PDF.js not loaded');
    const loadingTask = pdfjsLib.getDocument({ data: arrayBuffer });
    const pdf = await loadingTask.promise;
    const pages = [];
    for (let i = 1; i <= pdf.numPages; i++) {
        const page = await pdf.getPage(i);
        const tc = await page.getTextContent();
        const text = tc.items.map(it => it.str).join('');
        pages.push(text);
    }
    return pages.join('\n\n');
}

// ── DOCX ────────────────────────────────────────────────────
async function extractFromDocx(arrayBuffer) {
    if (typeof mammoth === 'undefined') throw new Error('mammoth not loaded');
    const result = await mammoth.extractRawText({ arrayBuffer });
    let text = result.value;
    // Append table text that extractRawText may skip
    if (result.messages && result.messages.length) {
        // mammoth messages are informational; ignore
    }
    return text;
}

// ── Plain Text ─────────────────────────────────────────────
async function extractFromText(arrayBuffer) {
    return new TextDecoder('utf-8').decode(arrayBuffer);
}

// ── Image (OCR via Tesseract.js, loaded on demand) ─────────
async function extractFromImage(file) {
    if (typeof Tesseract === 'undefined') {
        await loadScript('https://unpkg.com/tesseract.js@5/dist/tesseract.min.js');
    }
    showToast('Starting OCR… this may take a while', 'info');
    const result = await Tesseract.recognize(
        file,
        'eng',
        {
            logger: m => console.log('[Tesseract]', m.status, m?.progress ?? '', m?.data?.progress ?? '')
        }
    );
    const text = result.data?.text || '';
    await result.worker?.terminate?.();
    return text;
}

// ── Dynamic script loader ──────────────────────────────────
function loadScript(src) {
    return new Promise((resolve, reject) => {
        const s = document.createElement('script');
        s.src = src;
        s.onload = resolve;
        s.onerror = reject;
        document.head.appendChild(s);
    });
}

// ===== Parse CV =====
let isParsing = false;

async function parseCV() {
    if (!currentFile || isParsing) return;
    if (!rawText.trim()) {
        showToast('No text to parse. Select a file first.', 'warning');
        return;
    }
    isParsing = true;
    $('parseBtn').disabled = true;
    $('progressCard').style.display = 'block';
    $('progressCard').querySelector('.progress-card__header i').className = 'fas fa-cog fa-spin';
    $('progressTitle').textContent = 'Parsing your CV…';
    $('progressSub').textContent = 'Extracting structured data…';
    $('progressBar').style.width = '0%';
    $('parseBtn').style.display = 'none';

    let progress = 0;
    const interval = setInterval(() => {
        progress += Math.random() * 8;
        if (progress > 85) progress = 85;
        $('progressBar').style.width = progress.toFixed(1) + '%';
    }, 200);

    try {
        // Attempt LLM call if configured
        let data = null, llmUsed = false, warning = null;

        if (config.llmUrl) {
            $('progressSub').textContent = 'Querying local LLM…';
            const llmResult = await callLLM(rawText);
            if (llmResult) {
                data = llmResult;
                llmUsed = true;
            } else {
                warning = "LLM not reachable or returned no data. Using built-in fallback parser (lower accuracy).";
            }
        } else {
            warning = "No LLM endpoint configured. Using built-in fallback parser (lower accuracy).";
        }

        if (!data) {
            $('progressSub').textContent = 'Running fallback parser…';
            data = fallbackExtract(rawText);
        }

        data = validateAndClean(data);
        clearInterval(interval);
        $('progressBar').style.width = '100%';
        $('progressTitle').textContent = '✓ Parsing complete!';
        setTimeout(() => {
            $('progressCard').style.display = 'none';
            populateForm(data);
            $('editCard').style.display = 'block';

            // Update method badge
            const badge = $('parseMethodBadge');
            if (llmUsed) {
                badge.textContent = 'AI-Powered Parsing';
                badge.className = 'badge badge--info';
            } else {
                badge.textContent = 'Fallback Parser';
                badge.className = 'badge badge--warning';
            }

            if (warning) {
                showToast(warning, 'warning', 8000);
            } else {
                showToast('CV parsed successfully with AI-powered extraction!', 'success');
            }
        }, 300);
    } catch (err) {
        clearInterval(interval);
        $('progressBar').style.width = '100%';
        $('progressTitle').textContent = '✗ Parsing failed';
        showToast('Parse error: ' + err.message, 'error');
        setTimeout(() => $('progressCard').style.display = 'none', 1500);
    } finally {
        isParsing = false;
        $('parseBtn').style.display = 'inline-flex';
        $('parseBtn').disabled = false;
    }
}

// ===== LLM Call =====
const LLM_PROMPT_TEMPLATE = `You are an expert CV parser. Extract the following information from the CV text below.
Return ONLY valid JSON (no additional commentary) with these exact keys:
{
  "full_name": "",
  "email": "",
  "phone": "",
  "location": "",
  "linkedin": "",
  "website": "",
  "professional_summary": "",
  "work_experience": [
    { "job_title": "", "company": "", "start_date": "", "end_date": "", "description": "" }
  ],
  "education": [
    { "degree": "", "institution": "", "start_date": "", "end_date": "" }
  ],
  "skills": [],
  "certifications": [],
  "languages": []
}

Rules:
- If a field is missing, leave it as empty string or empty list.
- Dates should be in "YYYY-MM-DD" format if possible, otherwise "YYYY-MM" or "YYYY".
- For work experience and education, include all entries, preserving chronological order.
- The "skills" array should contain individual skills, not categories.
- Do NOT invent information; only extract what is present.
- The output must be a single JSON object.

CV Text:
---
%TEXT%
---`;

async function callLLM(text) {
    if (!config.llmUrl) return null;

    const prompt = LLM_PROMPT_TEMPLATE.replace('%TEXT%', text);

    const headers = { 'Content-Type': 'application/json' };
    if (config.apiKey) headers['Authorization'] = `Bearer ${config.apiKey}`;

    const payload = {
        model: config.llmModel,
        messages: [
            { role: 'system', content: 'You extract structured data from CVs. Respond only with JSON.' },
            { role: 'user', content: prompt }
        ],
        temperature: 0.1,
        max_tokens: 3000
    };

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), (config.timeout || 30) * 1000);

    try {
        const resp = await fetch(config.llmUrl, {
            method: 'POST',
            headers,
            body: JSON.stringify(payload),
            signal: controller.signal
        });
        clearTimeout(timeout);
        if (!resp.ok) return null;
        const json = await resp.json();
        let content = json.choices?.[0]?.message?.content || '';
        // Strip markdown code fences
        content = content.replace(/^```json\n?/, '').replace(/\n?```$/, '').trim();
        return JSON.parse(content);
    } catch (err) {
        console.warn('LLM call failed:', err);
        clearTimeout(timeout);
        return null;
    }
}

async function testLLMConnection() {
    const btn = $('testConnectionBtn');
    const status = $('connectionStatus');
    btn.disabled = true;
    btn.innerHTML = '<span class="spinner"></span> Testing…';
    status.innerHTML = '';

    try {
        const resp = await fetch(config.llmUrl, {
            method: 'GET',
            signal: AbortSignal.timeout(10_000)
        });
        // 200, 401, 404 all indicate the server is reachable
        const reachable = [200, 401, 404].includes(resp.status);
        if (reachable) {
            status.innerHTML = '<span class="badge badge--success">Connected</span>';
            showToast('LLM is reachable', 'success', 2500);
        } else {
            status.innerHTML = '<span class="badge badge--warning">Unusual response</span>';
        }
    } catch {
        status.innerHTML = '<span class="badge badge--danger">Unreachable</span>';
        showToast('Could not connect to LLM endpoint', 'error');
    } finally {
        btn.disabled = false;
        btn.innerHTML = '<i class="fas fa-plug"></i> Test Connection';
    }
}

