// ===== Fallback Regex Parser (ported from Python backend) =====
function fallbackExtract(text) {
    const data = {
        full_name: "", email: "", phone: "", location: "",
        linkedin: "", website: "", professional_summary: "",
        work_experience: [], education: [],
        skills: [], certifications: [], languages: []
    };

    // Email
    const emailM = text.match(/[\w\.-]+@[\w\.-]+\.\w+/);
    if (emailM) data.email = emailM[0];

    // Phone
    const phoneM = text.match(/(\+?\d{1,3}[\s-]?)?(\(?\d{2,4}\)?[\s-]?)?\d{3,4}[\s-]?\d{3,4}/);
    if (phoneM) data.phone = phoneM[0].trim();

    // LinkedIn
    const linkedinM = text.match(/linkedin\.com\/in\/[A-Za-z0-9\-_]+/i);
    if (linkedinM) data.linkedin = linkedinM[0];

    // Website (non-linkedin)
    const websiteM = text.match(/(?:https?:\/\/)?(?:www\.)?[a-zA-Z0-9\-]+\.[a-zA-Z]{2,}(?:\/[^\s]*)?/);
    if (websiteM && !websiteM[0].toLowerCase().includes('linkedin')) {
        data.website = websiteM[0];
    }

    // Name: first non-empty line without contact keywords, <= 6 words
    const lines = text.split('\n').map(l => l.trim()).filter(l => l);
    const skipWords = ["email", "phone", "address", "linkedin", "www", "http", "@",
                       "curriculum", "resume", "cv"];
    for (let i = 0; i < Math.min(lines.length, 10); i++) {
        const lower = lines[i].toLowerCase();
        if (!skipWords.some(w => lower.includes(w)) &&
            lines[i].split(/\s+/).length <= 6) {
            data.full_name = toTitleCase(lines[i]);
            break;
        }
    }

    // Location: "City, Country" pattern
    const locM = text.match(/([A-Za-z]+(?:[ ,]+[A-Za-z]+){0,3}),\s*([A-Za-z]{2,})/);
    if (locM) data.location = locM[0].trim();

    // Skills
    const skillsMatch = text.match(/skills?\s*:?\s*([\s\S]*?)(?=\n\s*\n|\n[A-Z][a-z]+:)/i);
    if (skillsMatch) {
        const skills = skillsMatch[1].split(/[,\n•|]/).map(s => s.trim()).filter(Boolean);
        data.skills = skills.slice(0, 30);
    }

    // Work Experience
    const expMatch = text.match(
        /(?:work\s*experience|employment|professional\s*experience)\s*:?\s*([\s\S]*?)(?=\n\s*(?:education|skills|certifications|languages)\s*:?\s*|$)/i
    );
    if (expMatch) {
        data.work_experience = parseExperienceEntries(expMatch[1]);
    }

    // Education
    const eduMatch = text.match(
        /education\s*:?\s*([\s\S]*?)(?=\n\s*(?:skills|work\s*experience|certifications|languages)\s*:?\s*|$)/i
    );
    if (eduMatch) {
        data.education = parseEducationEntries(eduMatch[1]);
    }

    // Certifications
    const certMatch = text.match(/certifications?\s*:?\s*([\s\S]*?)(?=\n\s*\n|\n[A-Z][a-z]+:)/i);
    if (certMatch) {
        data.certifications = certMatch[1].split(/[,\n•|]/).map(s => s.trim()).filter(Boolean);
    }

    // Languages
    const langMatch = text.match(/languages?\s*:?\s*([\s\S]*?)(?=\n\s*\n|\n[A-Z][a-z]+:)/i);
    if (langMatch) {
        data.languages = langMatch[1].split(/[,\n•|]/).map(s => s.trim()).filter(Boolean);
    }

    return data;
}

function parseExperienceEntries(text) {
    const entries = [];
    let current = [];
    const lines = text.split('\n').map(l => l.trim()).filter(l => l);

    for (const line of lines) {
        const hasDate = /\b(19|20)\d{2}\b/.test(line);
        if (hasDate && current.length > 0) {
            entries.push(current.join('\n'));
            current = [];
        }
        current.push(line);
    }
    if (current.length) entries.push(current.join('\n'));

    return entries.map(entry => {
        const lines = entry.split('\n');
        const dates = entry.match(/(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?\s+\d{4}|\d{4}/gi) || [];
        return {
            job_title: lines[0] || '',
            company: '',
            start_date: dates[0] || '',
            end_date: dates[1] || '',
            description: lines.slice(1).join('\n') || ''
        };
    });
}

function parseEducationEntries(text) {
    const entries = [];
    let current = [];
    const lines = text.split('\n').map(l => l.trim()).filter(l => l);

    for (const line of lines) {
        const hasDate = /\b(19|20)\d{2}\b/.test(line);
        if (hasDate && current.length > 0) {
            entries.push(current.join('\n'));
            current = [];
        }
        current.push(line);
    }
    if (current.length) entries.push(current.join('\n'));

    return entries.map(entry => {
        const lines = entry.split('\n');
        const dates = entry.match(/(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?\s+\d{4}|\d{4}/gi) || [];
        return {
            degree: lines[0] || '',
            institution: lines.slice(1).join(' ') || '',
            start_date: dates[0] || '',
            end_date: dates[1] || ''
        };
    });
}

// ===== Validation =====
const CV_SCHEMA = {
    full_name: 'string', email: 'string', phone: 'string', location: 'string',
    linkedin: 'string', website: 'string', professional_summary: 'string',
    work_experience: 'array', education: 'array',
    skills: 'array', certifications: 'array', languages: 'array'
};

function validateAndClean(data) {
    const cleaned = {};
    for (const [key, type] of Object.entries(CV_SCHEMA)) {
        if (!(key in data) || typeof data[key] !== type) {
            cleaned[key] = type === 'array' ? [] : '';
        } else {
            cleaned[key] = data[key];
        }
    }

    // Clean work experience
    const we = [];
    for (const exp of cleaned.work_experience) {
        if (exp && typeof exp === 'object') {
            we.push({
                job_title: exp.job_title || '',
                company: exp.company || '',
                start_date: exp.start_date || '',
                end_date: exp.end_date || '',
                description: exp.description || ''
            });
        }
    }
    cleaned.work_experience = we;

    // Clean education
    const edu = [];
    for (const e of cleaned.education) {
        if (e && typeof e === 'object') {
            edu.push({
                degree: e.degree || '',
                institution: e.institution || '',
                start_date: e.start_date || '',
                end_date: e.end_date || ''
            });
        }
    }
    cleaned.education = edu;

    // Clean list fields
    for (const key of ['skills', 'certifications', 'languages']) {
        cleaned[key] = cleaned[key].map(i => String(i)).filter(i => i);
    }

    return cleaned;
}

