// ===== DOCX Generation =====
async function generateDocx() {
    const data = collectFormData();

    // Validate
    if (!data.full_name) { showToast('Please enter a full name.', 'error'); return; }
    if (!data.email) { showToast('Please enter an email address.', 'error'); return; }

    const btn = $('generateBtn');
    const original = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = '<span class="spinner"></span> Generating…';

    try {
        if (typeof docx === 'undefined') throw new Error('DOCX library not loaded');

        const { Document, Paragraph, HeadingLevel, Packer, AlignmentType } = docx;

        const children = [];

        // Title
        children.push(new Paragraph({
            text: data.full_name,
            heading: HeadingLevel.TITLE,
            alignment: AlignmentType.CENTER
        }));

        // Contact info
        const contacts = [];
        if (data.email) contacts.push(`Email: ${data.email}`);
        if (data.phone) contacts.push(`Phone: ${data.phone}`);
        if (data.location) contacts.push(`Location: ${data.location}`);
        if (data.linkedin) contacts.push(`LinkedIn: ${data.linkedin}`);
        if (data.website) contacts.push(`Website: ${data.website}`);
        if (contacts.length) {
            children.push(new Paragraph({ text: contacts.join(' | '), alignment: AlignmentType.CENTER }));
        }

        // Professional Summary
        if (data.professional_summary) {
            children.push(new Paragraph({ text: 'Professional Summary', heading: HeadingLevel.HEADING_2 }));
            children.push(new Paragraph({ text: data.professional_summary }));
        }

        // Work Experience
        if (data.work_experience.length) {
            children.push(new Paragraph({ text: 'Work Experience', heading: HeadingLevel.HEADING_2 }));
            for (const exp of data.work_experience) {
                let titleCompany = exp.job_title || '';
                if (exp.company) titleCompany += ` at ${exp.company}`;
                let dates = '';
                if (exp.start_date || exp.end_date) {
                    dates = ` (${exp.start_date || ''} - ${exp.end_date || ''})`;
                }
                children.push(new Paragraph({
                    text: titleCompany + dates,
                    heading: HeadingLevel.HEADING_3
                }));
                if (exp.description) {
                    children.push(new Paragraph({ text: exp.description }));
                }
            }
        }

        // Education
        if (data.education.length) {
            children.push(new Paragraph({ text: 'Education', heading: HeadingLevel.HEADING_2 }));
            for (const edu of data.education) {
                let degree = edu.degree || '';
                if (edu.institution) degree += ` - ${edu.institution}`;
                let dates = '';
                if (edu.start_date || edu.end_date) {
                    dates = ` (${edu.start_date || ''} - ${edu.end_date || ''})`;
                }
                children.push(new Paragraph({ text: degree + dates }));
            }
        }

        // Skills
        if (data.skills.length) {
            children.push(new Paragraph({ text: 'Skills', heading: HeadingLevel.HEADING_2 }));
            children.push(new Paragraph({ text: data.skills.join(', ') }));
        }

        // Certifications
        if (data.certifications.length) {
            children.push(new Paragraph({ text: 'Certifications', heading: HeadingLevel.HEADING_2 }));
            for (const cert of data.certifications) {
                children.push(new Paragraph({ text: cert, bullet: { level: 0 } }));
            }
        }

        // Languages
        if (data.languages.length) {
            children.push(new Paragraph({ text: 'Languages', heading: HeadingLevel.HEADING_2 }));
            children.push(new Paragraph({ text: data.languages.join(', ') }));
        }

        const doc = new Document({
            sections: [{ properties: {}, children }]
        });

        const blob = await Packer.toBlob(doc);
        saveAs(blob, 'clean_cv.docx');
        showSuccessToast('Your clean CV has been downloaded!');
    } catch (err) {
        showToast('Error generating DOCX: ' + err.message, 'error');
    } finally {
        btn.disabled = false;
        btn.innerHTML = original;
    }
}

// ===== Toast =====
function showToast(message, type = 'info', duration = 5000) {
    let container = document.querySelector('.toast-container');
    if (!container) {
        container = document.createElement('div');
        container.className = 'toast-container';
        document.body.appendChild(container);
    }
    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;
    const icons = { success: '✅', error: '❌', info: 'ℹ️', warning: '⚠️' };
    toast.innerHTML = `
        <span class="toast-icon">${icons[type] || 'ℹ️'}</span>
        <div class="toast-content">${escapeHtml(message)}</div>
        <button class="toast-close" onclick="this.parentElement.remove()">&times;</button>
    `;
    container.appendChild(toast);
    setTimeout(() => {
        if (toast.parentElement) {
            toast.style.opacity = '0';
            toast.style.transition = 'opacity 0.3s';
            setTimeout(() => toast.remove(), 300);
        }
    }, duration);
}

const showSuccessToast = (msg, dur) => showToast(msg, 'success', dur);
const showError   = (msg, dur) => showToast(msg, 'error', dur);
const showInfo    = (msg, dur) => showToast(msg, 'info', dur);
const showWarning = (msg, dur) => showToast(msg, 'warning', dur);

// ===== Utilities =====
function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = String(text);
    return div.innerHTML;
}

function formatFileSize(bytes) {
    if (!bytes) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
}

function toTitleCase(str) {
    return str.replace(/\w\S*/g, w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase());
}

