    --warning-text: #92400e;
    --error-bg: #fee2e2;
    --error-text: #991b1b;
    --success-bg: #dcfce7;
    --success-text: #166534;

    --border: #e5e7eb;
    --border-dark: #d1d5db;
    --bg: #f9fafb;
    --text: #1f2937;
    --text-secondary: #6b7280;
    --card-bg: #ffffff;

